pragma solidity ^0.8.0;
contract AlchemyPowerCraftStaking is Ownable {
    using SafeERC20 for IERC20;
    struct UserInfo {
        uint256 balance;
        uint256 reward;
        uint256 rewardPerTokenPaid;
        uint256 paidOut;
    }
    IERC20 public craft;
    IAlchemyPower public alchemyPower;
    ITimeProvider public immutable timeProvider;
    uint256 private _totalBalance;
    uint256 public rewardPerTokenStored;
    uint256 public lastUpdateTime;
    uint256 public constant tokensPerSecond = .003e18;
    mapping (address => UserInfo) public userInfos;
    event CraftStaked(address indexed account, uint256 amount);
    event CraftUnstaked(address indexed account, uint256 amount);
    constructor(IAlchemyPower alchemyPower_, IERC20 craft_, ITimeProvider timeProvider_) {
        alchemyPower = alchemyPower_;
        craft = craft_;
        timeProvider = timeProvider_;
    }
    function _rewardPerToken() public view returns (uint256) {
        if (_totalBalance == 0)
            return rewardPerTokenStored;
        return rewardPerTokenStored + (timeProvider.getTimestamp() - lastUpdateTime) * tokensPerSecond * 1e18 / _totalBalance;
    }
    function pendingCraftPower(address account) public view returns (uint256) {
        UserInfo storage userInfo = userInfos[account];
        return userInfo.balance * (_rewardPerToken() - userInfo.rewardPerTokenPaid) / 1e18 + userInfo.reward;
    }
    function _updateReward(address account) private {
        rewardPerTokenStored = _rewardPerToken();
        lastUpdateTime = timeProvider.getTimestamp();
        if (account != address(0)) {
            UserInfo storage userInfo = userInfos[account];
            userInfo.reward = pendingCraftPower(account);
            userInfo.rewardPerTokenPaid = rewardPerTokenStored;
        }
    }
    function stake(uint256 amount) external {
        require(amount > 0, "cannot stake 0");
        _updateReward(msg.sender);
        _totalBalance += amount;
        userInfos[msg.sender].balance += amount;
        craft.safeTransferFrom(msg.sender, address(this), amount);
        emit CraftStaked(msg.sender, amount);
    }
    function unstake(uint256 amount) external {
        require(amount > 0, "cannot unstake 0");
        UserInfo storage userInfo = userInfos[msg.sender];
        require(amount <= userInfo.balance, "insufficient staked balance");
        _updateReward(msg.sender);
        _totalBalance -= amount;
        userInfo.balance -= amount;
        userInfo.reward = 0;
        uint256 paidOut = userInfo.paidOut;
        userInfo.paidOut = 0;
        alchemyPower.burn(msg.sender, paidOut);
        craft.safeTransfer(msg.sender, amount);
        emit CraftUnstaked(msg.sender, amount);
    }
    function claimAlchemyPower() external {
        _updateReward(msg.sender);
        UserInfo storage userInfo = userInfos[msg.sender];
        uint256 reward = userInfo.reward;
        require(reward > 0, "nothing to claim");
        userInfo.reward = 0;
        userInfo.paidOut += reward;
        alchemyPower.mint(msg.sender, reward);
    }
}

