pragma solidity ^0.8.0;
contract AIMStaking is Ownable {
    using SafeERC20 for IERC20;
    IERC20 public platformToken;
    uint256 public constant FIXED_APY = 60; // 60% fixed APY
    uint256 public constant LOCK_DAYS = 1; // 1 days lockup period
    uint256 public constant SECONDS_IN_A_YEAR = 365 * 24 * 60 * 60;
    uint256 public constant DECIMALS_MULTIPLIER = 1e18;
    uint256 public totalStaked;
    // Enable/Disable reward status
    bool public rewardsEnabled = true;
    // Circuit breaker variables for emergency stop mechanism
    bool public stopped = false;
    struct StakerInfo {
        uint256 stakedAmount;
        uint256 lastClaimTimestamp;
        uint256 lockTimestamp;
    }
    mapping(address => StakerInfo) public stakers;
    event Staked(address indexed user, uint256 amount);
    event Unstaked(address indexed user, uint256 amount);
    event RewardsClaimed(address indexed user, uint256 rewards);
    modifier stopInEmergency() {
        require(!stopped, "Stopped by owner");
        _;
    }
    modifier onlyInEmergency() {
        require(stopped, "Not in emergency state");
        _;
    }
    /// @notice Constructor to initialize the contract
    /// @param _platformToken The address of the token to be staked
    constructor(IERC20 _platformToken) {
        platformToken = _platformToken;
    }
    /// @notice Allows the contract owner to toggle reward generation status
    function toggleRewards() external onlyOwner {
        rewardsEnabled = !rewardsEnabled;
    }
    /// @notice Allows the contract owner to stop the contract
    function stopContract() external onlyOwner {
        stopped = true;
    }
    /// @notice Allows the contract owner to resume the contract
    function resumeContract() external onlyOwner onlyInEmergency {
        stopped = false;
    }
    /// @notice Allows a user to stake tokens
    /// @param amount The amount of tokens to stake
    function stake(uint256 amount) external stopInEmergency {
        require(amount > 0, "Amount must be greater than 0");
        platformToken.safeTransferFrom(msg.sender, address(this), amount);
        StakerInfo storage staker = stakers[msg.sender];
        // If the user is staking for the first time, set lastClaimTimestamp to now
        if (staker.stakedAmount == 0) {
            staker.lastClaimTimestamp = block.timestamp;
        }
        _updateRewards(msg.sender);
        staker.stakedAmount += amount;
        staker.lockTimestamp = block.timestamp + LOCK_DAYS * 1 days;
        totalStaked += amount;
        emit Staked(msg.sender, amount);
    }
    /// @notice Allows a user to unstake tokens
    /// @param amount The amount of tokens to unstake
    function unstake(uint256 amount) external stopInEmergency {
        StakerInfo storage staker = stakers[msg.sender];
        require(amount > 0 && staker.stakedAmount >= amount, "Invalid amount");
        require(block.timestamp >= staker.lockTimestamp,
            "Tokens are still locked");
        _updateRewards(msg.sender);
        staker.stakedAmount -= amount;
        totalStaked -= amount;
        platformToken.safeTransfer(msg.sender, amount);
        emit Unstaked(msg.sender, amount);
    }
    /// @notice Allows a user to claim their rewards
    function claimRewards() external stopInEmergency {
        _updateRewards(msg.sender);
    }
    /// @notice Get the staker's info and pending rewards
    /// @param user The address of the staker
    /// @return stakedAmount The total staked amount of the user
    /// @return pendingRewards The total rewards that the user can claim
    function getStakerInfo(address user)
        external
        view
        returns (uint256 stakedAmount, uint256 pendingRewards)
    {
        StakerInfo storage staker = stakers[user];
        stakedAmount = staker.stakedAmount;
        pendingRewards = _calculatePendingRewards(user);
    }
    /// @notice Get the remaining lock time for a user's tokens
    /// @param user The address of the staker
    /// @return The remaining lock time in seconds
    function getLockTimeLeft(address user) external view returns (uint256) {
        StakerInfo storage staker = stakers[user];
        if (block.timestamp >= staker.lockTimestamp) {
            return 0;
        } else {
            return staker.lockTimestamp - block.timestamp;
        }
    }
    /// @notice Internal function to update user rewards
    /// @param user The address of the staker
    function _updateRewards(address user) internal {
        if (rewardsEnabled) {
            StakerInfo storage staker = stakers[user];
            uint256 pendingRewards = _calculatePendingRewards(user);
            if (pendingRewards > 0) {
                staker.lastClaimTimestamp = block.timestamp;
                platformToken.safeTransfer(user, pendingRewards);
                emit RewardsClaimed(user, pendingRewards);
            } else {
                staker.lastClaimTimestamp = block.timestamp;
            }
        }
    }
    /// @notice Internal function to calculate pending rewards for a user
    /// @param user The address of the staker
    /// @return The amount of pending rewards for the user
    function _calculatePendingRewards(address user)
        internal
        view
        returns (uint256)
    {
        if (rewardsEnabled) {
            StakerInfo storage staker = stakers[user];
            uint256 timeSinceLastClaim = block.timestamp -
                staker.lastClaimTimestamp;
            uint256 rewardRate = (staker.stakedAmount *
                FIXED_APY *
                timeSinceLastClaim) / (SECONDS_IN_A_YEAR * 100);
            return rewardRate;
        } else {
            return 0;
        }
    }
}

pragma solidity ^0.8.0;
pragma solidity ^0.8.0;
contract IdleCDOTrancheRewards is Initializable, PausableUpgradeable, OwnableUpgradeable, ReentrancyGuardUpgradeable, IIdleCDOTrancheRewards, IdleCDOTrancheRewardsStorage {
  using SafeERC20Upgradeable for IERC20Detailed;
  constructor() {
    tranche = address(1);
  }
  function initialize(address _trancheToken, address[] memory _rewards, address _owner,
    address _idleCDO, address _governanceRecoveryFund, uint256 _coolingPeriod) public initializer {
    require(tranche == address(0), 'Initialized');
    require(_owner != address(0) && _trancheToken != address(0) && _idleCDO != address(0) && _governanceRecoveryFund != address(0), "IS_0");
    OwnableUpgradeable.__Ownable_init();
    ReentrancyGuardUpgradeable.__ReentrancyGuard_init();
    PausableUpgradeable.__Pausable_init();
    transferOwnership(_owner);
    idleCDO = _idleCDO;
    tranche = _trancheToken;
    rewards = _rewards;
    governanceRecoveryFund = _governanceRecoveryFund;
    coolingPeriod = _coolingPeriod;
  }
  function stake(uint256 _amount) external whenNotPaused override {
    _stake(msg.sender, msg.sender, _amount);
  }
  function stakeFor(address _user, uint256 _amount) external whenNotPaused override {
    require(msg.sender == idleCDO, "!AUTH");
    _stake(_user, msg.sender, _amount);
  }
  function _stake(address _user, address _payer, uint256 _amount) internal {
    if (_amount == 0) {
      return;
    }
    _updateUserIdx(_user, _amount);
    usersStakes[_user] += _amount;
    IERC20Detailed(tranche).safeTransferFrom(_payer, address(this), _amount);
    totalStaked += _amount;
  }
  function unstake(uint256 _amount) external nonReentrant override {
    if (_amount == 0) {
      return;
    }
    if (paused()) {
      address reward;
      for (uint256 i = 0; i < rewards.length; i++) {
        reward = rewards[i];
        usersIndexes[msg.sender][reward] = adjustedRewardIndex(reward);
      }
    } else {
      _claim();
    }
    usersStakes[msg.sender] -= _amount;
    IERC20Detailed(tranche).safeTransfer(msg.sender, _amount);
    totalStaked -= _amount;
  }
  function claim() whenNotPaused nonReentrant external {
    _claim();
  }
  function _claim() internal {
    address[] memory _rewards = rewards;
    for (uint256 i = 0; i < _rewards.length; i++) {
      address reward = _rewards[i];
      uint256 amount = expectedUserReward(msg.sender, reward);
      uint256 balance = IERC20Detailed(reward).balanceOf(address(this));
      if (amount > balance) {
        amount = balance;
      }
      usersIndexes[msg.sender][reward] = adjustedRewardIndex(reward);
      IERC20Detailed(reward).safeTransfer(msg.sender, amount);
    }
  }
  function expectedUserReward(address user, address reward) public view returns (uint256) {
    require(_includesAddress(rewards, reward), "!SUPPORTED");
    uint256 _globalIdx = adjustedRewardIndex(reward);
    uint256 _userIdx = usersIndexes[user][reward];
    if (_userIdx > _globalIdx) {
      return 0;
    }
    return ((_globalIdx - _userIdx) * usersStakes[user]) / ONE_TRANCHE_TOKEN;
  }
  function adjustedRewardIndex(address _reward) public view returns (uint256 _index) {
    uint256 _totalStaked = totalStaked;
    uint256 _lockedRewards = lockedRewards[_reward];
    _index = rewardsIndexes[_reward];
    if (_totalStaked > 0 && _lockedRewards > 0) {
      uint256 distance = block.number - lockedRewardsLastBlock[_reward];
      if (distance < coolingPeriod) {
        uint256 unlockedRewards = _lockedRewards * distance / coolingPeriod;
        uint256 lockedRewards = _lockedRewards - unlockedRewards;
        _index -= lockedRewards * ONE_TRANCHE_TOKEN / _totalStaked;
      }
    }
  }
  function depositReward(address _reward, uint256 _amount) external override {
    require(msg.sender == idleCDO, "!AUTH");
    require(_includesAddress(rewards, _reward), "!SUPPORTED");
    IERC20Detailed(_reward).safeTransferFrom(msg.sender, address(this), _amount);
    if (totalStaked > 0) {
      rewardsIndexes[_reward] += _amount * ONE_TRANCHE_TOKEN / totalStaked;
    }
    lockedRewards[_reward] = _amount;
    lockedRewardsLastBlock[_reward] = block.number;
  }
  function setCoolingPeriod(uint256 _newCoolingPeriod) external onlyOwner {
    coolingPeriod = _newCoolingPeriod;
  }
  function _updateUserIdx(address _user, uint256 _amountToStake) internal {
    address[] memory _rewards = rewards;
    uint256 userIndex;
    address reward;
    uint256 _currStake = usersStakes[_user];
    for (uint256 i = 0; i < _rewards.length; i++) {
      reward = _rewards[i];
      if (_currStake == 0) {
        usersIndexes[_user][reward] = rewardsIndexes[reward];
      } else {
        userIndex = usersIndexes[_user][reward];
        usersIndexes[_user][reward] = userIndex + (_amountToStake * (rewardsIndexes[reward] - userIndex) / (_currStake + _amountToStake));
      }
    }
  }
  function _includesAddress(address[] memory _array, address _val) internal pure returns (bool) {
    for (uint256 i = 0; i < _array.length; i++) {
      if (_array[i] == _val) {
        return true;
      }
    }
    return false;
  }
  function transferToken(address token, uint256 value) external onlyOwner nonReentrant {
    require(token != address(0), 'Address is 0');
    IERC20Detailed(token).safeTransfer(governanceRecoveryFund, value);
  }
  function pause() external onlyOwner {
    _pause();
  }
  function unpause() external onlyOwner {
    _unpause();
  }
}

