contract TenderFarm is Initializable, ITenderFarm, SelfPermit {
    IERC20 public token;
    ITenderToken public rewardToken;
    ITenderizer public tenderizer;
    /// @inheritdoc ITenderFarm
    uint256 public override totalStake;
    /// @inheritdoc ITenderFarm
    uint256 public override nextTotalStake;
    uint256 public CRF;
    struct Stake {
        uint256 stake;
        uint256 lastCRF;
    }
    mapping(address => Stake) public stakes;
    function initialize(IERC20 _stakeToken,
        ITenderToken _rewardToken,
        ITenderizer _tenderizer) external override initializer returns (bool) {
        token = _stakeToken;
        rewardToken = _rewardToken;
        tenderizer = _tenderizer;
        return true;
    }
    modifier onlyTenderizer() {
        require(msg.sender == address(tenderizer));
        _;
    }
    /// @inheritdoc ITenderFarm
    function farm(uint256 _amount) external override {
        _farmFor(msg.sender, _amount);
    }
    /// @inheritdoc ITenderFarm
    function farmWithPermit(uint256 _amount,
        uint256 _deadline,
        uint8 _v,
        bytes32 _r,
        bytes32 _s) external override {
        selfPermit(address(token), _amount, _deadline, _v, _r, _s);
        _farmFor(msg.sender, _amount);
    }
    /// @inheritdoc ITenderFarm
    function farmFor(address _for, uint256 _amount) external override {
        _farmFor(_for, _amount);
    }
    /// @inheritdoc ITenderFarm
    function unfarm(uint256 _amount) external override {
        _unfarm(msg.sender, _amount);
    }
    /// @inheritdoc ITenderFarm
    function harvest() external override {
        _harvest(msg.sender);
    }
    /// @inheritdoc ITenderFarm
    function addRewards(uint256 _amount) external override onlyTenderizer {
        uint256 _nextStake = nextTotalStake;
        require(_nextStake > 0, "NO_STAKE");
        totalStake = _nextStake;
        uint256 shares = rewardToken.tokensToShares(_amount);
        CRF += MathUtils.percPoints(shares, _nextStake);
        require(rewardToken.transferFrom(msg.sender, address(this), _amount), "TRANSFER_FAILED");
        emit RewardsAdded(_amount);
    }
    /// @inheritdoc ITenderFarm
    function availableRewards(address _for) external view override returns (uint256) {
        return rewardToken.sharesToTokens(_availableRewardShares(_for));
    }
    /// @inheritdoc ITenderFarm
    function stakeOf(address _of) external view override returns (uint256) {
        return _stakeOf(_of);
    }
    // INTERNAL FUNCTIONS
    function _farmFor(address _for, uint256 _amount) internal {
        _harvest(_for);
        stakes[_for].stake += _amount;
        nextTotalStake += _amount;
        require(token.transferFrom(msg.sender, address(this), _amount), "TRANSFERFROM_FAIL");
        emit Farm(_for, _amount);
    }
    function _unfarm(address _for, uint256 _amount) internal {
        Stake storage _stake = stakes[_for];
        require(_amount <= _stake.stake, "AMOUNT_EXCEEDS_STAKE");
        _harvest(_for);
        _stake.stake -= _amount;
        nextTotalStake -= _amount;
        require(token.transfer(_for, _amount), "TRANSFER_FAIL");
        emit Unfarm(_for, _amount);
    }
    function _harvest(address _for) internal {
        Stake storage _stake = stakes[_for];
        // Calculate available rewards
        uint256 rewards = _availableRewardShares(_for);
        // Checkpoint CRF
        _stake.lastCRF = CRF;
        if (rewards > 0) {
            uint256 rewardTokens = rewardToken.sharesToTokens(rewards);
            require(rewardToken.transfer(_for, rewardTokens), "TRANSFER_FAIL");
            emit Harvest(_for, rewardTokens);
        }
    }
    function _availableRewardShares(address _for) internal view returns (uint256) {
        Stake storage _stake = stakes[_for];
        if (CRF == 0) return 0;
        return MathUtils.percOf(_stake.stake, CRF - _stake.lastCRF);
    }
    function _stakeOf(address _of) internal view returns (uint256) {
        return stakes[_of].stake;
    }
    function setTenderizer(ITenderizer _tenderizer) external override onlyTenderizer {
        tenderizer = _tenderizer;
    }
}

pragma solidity ^0.7.5;
contract QUAI_Staking is Ownable {
	using SafeMath for uint256;
	address public constant quaiToken = 0x40821CD074dfeCb1524286923bC69315075b5c89; //token to stake
	uint256 public constant stakingPeriod = 30 days; //period over which tokens are locked after staking
	uint256 public stakingEnd; //point after which staking rewards cease to accumulate
	uint256 public rewardRate = 14; //14% linear return per staking period
	uint256 public totalStaked; //sum of all user stakes
	uint256 public maxTotalStaked = 58e23; //5.8 million tokens
	uint256 public minStaked = 1e21; //1000 tokens. min staked per user
	mapping (address => uint256) public stakedTokens; //amount of tokens that address has staked
	mapping (address => uint256) public lastStaked; 
	mapping (address => uint256) public totalEarnedTokens; //total tokens earned through staking by each user
	constructor(){
		stakingEnd = (block.timestamp + 180 days);
	}
	function deposit(uint256 amountTokens) external {
		require((stakedTokens[msg.sender] >= minStaked || amountTokens >= minStaked), "deposit: must exceed minimum stake");
		require(totalStaked + amountTokens <= maxTotalStaked, "deposit: amount would exceed max stake. call updateStake to claim dividends");
		updateStake();
		IERC20(quaiToken).transferFrom(msg.sender, address(this), amountTokens);
		stakedTokens[msg.sender] += amountTokens;
		totalStaked += amountTokens;
	}
	function updateStake() public {
		uint256 stakedUntil = min(block.timestamp, stakingEnd);
		uint256 periodStaked = stakedUntil.sub(lastStaked[msg.sender]);
		uint256 dividends;
		if(periodStaked < stakingPeriod) {
			dividends = periodStaked.mul(stakedTokens[msg.sender]).mul(rewardRate).div(stakingPeriod).div(100);
		} else {
			dividends = stakedTokens[msg.sender].mul(rewardRate).div(100);
		}
		lastStaked[msg.sender] = stakedUntil;
		if(totalStaked + dividends > maxTotalStaked) {
			IERC20(quaiToken).transfer(msg.sender, dividends);
			totalEarnedTokens[msg.sender] += dividends;
		} else {
			stakedTokens[msg.sender] += dividends;
			totalStaked += dividends;
			totalEarnedTokens[msg.sender] += dividends;
		}
	}
	function withdrawDividends() external {
		uint256 stakedUntil = min(block.timestamp, stakingEnd);
		uint256 periodStaked = stakedUntil.sub(lastStaked[msg.sender]);
		uint256 dividends;
		if(periodStaked < stakingPeriod) {
			dividends = periodStaked.mul(stakedTokens[msg.sender]).mul(rewardRate).div(stakingPeriod).div(100);
		} else {
			dividends = stakedTokens[msg.sender].mul(rewardRate).div(100);
		}
		lastStaked[msg.sender] = stakedUntil;
		IERC20(quaiToken).transfer(msg.sender, dividends);
		totalEarnedTokens[msg.sender] += dividends;
	}
    function min(uint256 a, uint256 b) internal pure returns(uint256) {
        return a < b ? a : b;
    }
	function unstake() external {
		uint256 timeSinceStake = (block.timestamp).sub(lastStaked[msg.sender]);
		require(timeSinceStake >= stakingPeriod || block.timestamp > stakingEnd, "unstake: staking period for user still ongoing");
		updateStake();
		uint256 toTransfer = stakedTokens[msg.sender];
		stakedTokens[msg.sender] = 0;
		IERC20(quaiToken).transfer(msg.sender, toTransfer);
		totalStaked = totalStaked.sub(toTransfer);
	}
	function getPendingDivs(address user) external view returns(uint256) {
		uint256 stakedUntil = min(block.timestamp, stakingEnd);
		uint256 periodStaked = stakedUntil.sub(lastStaked[user]);
		uint256 dividends;
		if(periodStaked < stakingPeriod) {
			dividends = periodStaked.mul(stakedTokens[user]).mul(rewardRate).div(stakingPeriod).div(100);
		} else {
			dividends = stakedTokens[user].mul(rewardRate).div(100);
		}
		return(dividends);
	}
	function updateMinStake(uint256 newMinStake) external onlyOwner() {
		minStaked = newMinStake;
	}
	function updateStakingEnd(uint256 newStakingEnd) external onlyOwner() {
		require(newStakingEnd >= block.timestamp, "updateStakingEnd: newStakingEnd must be in future");
		stakingEnd = newStakingEnd;
	}
	function updateRewardRate(uint256 newRewardRate) external onlyOwner() {
		require(newRewardRate <= 100, "what are you, crazy?");
		rewardRate = newRewardRate;
	}
	function updateMaxTotalStaked(uint256 newMaxTotalStaked) external onlyOwner() {
		maxTotalStaked = newMaxTotalStaked;
	}
	function recoverTokens(address tokenAddress, address dest, uint256 amountTokens) external onlyOwner() {
		require(tokenAddress != quaiToken, "recoverTokens: cannot move staked token");
		IERC20(tokenAddress).transfer(dest, amountTokens);
	}
	function recoverQUAI() external onlyOwner() {
		require(block.timestamp >= (stakingEnd + 30 days), "recoverQUAI: too early");
		uint256 amountToSend = IERC20(quaiToken).balanceOf(address(this));
		IERC20(quaiToken).transfer(msg.sender, amountToSend);
	}
}

pragma solidity 0.4.20;
contract MoonInc {
    string public constant name  = "Cookie | Moon, Inc.";
    string public constant symbol = "Cookie";
    uint8 public constant decimals = 18;
    // Total balances
    uint256 public totalEtherCookieResearchPool; // Eth dividends to be split between players' cookie production
    uint256 public totalCookieProduction;
    uint256 private roughSupply;
    uint256 private lastTotalCookieSaveTime; // Last time any player claimed their produced cookie
    // Balances for each player
    mapping(address => uint256) public cookieProduction;
    mapping(address => uint256) public cookieBalance;
    mapping(address => uint256) private lastCookieSaveTime; // Last time player claimed their produced cookie
    // Mapping of approved ERC20 transfers (by player)
    mapping(address => mapping(address => uint256)) internal allowed;
    // Production unit contracts
    ProductionUnitToken[] public productionUnitTokenContracts;
    mapping(address => bool) productionUnitTokenContractAddresses;
    // Store the production unit start time to calculate sell price.
    uint256[] public tokenContractStartTime;
    uint256 public constant firstUnitStartTime = 1526763600; // TODO: change this in main launch contract
    // ERC20 events
    event Transfer(address indexed from, address indexed to, uint tokens);
    event Approval(address indexed tokenOwner, address indexed spender, uint tokens);
    // Constructor
    function MoonInc() public payable {
        // Create first production unit (Space Kitty)
        createProductionUnit1Beta();
        // Create first production unit (Space Rabbit)
        // createProductionUnit2Beta();
        // Create first production unit (Space Hamster)
        // createProductionUnit3Beta();
    }
    function() public payable {
        // Fallback will add to research pot
        totalEtherCookieResearchPool += msg.value;
    }
    // TODO: Create 7 createProductionUnit functions in main launch contract
    function createProductionUnit1Beta() public {
        require(productionUnitTokenContracts.length == 0);
        createProductionUnitTokenContract(10, 10, 10, 0.0000001 ether / 1000, 0.00000001 ether / 1000, 1, firstUnitStartTime);
    }
    function createProductionUnit2Beta() public {
        require(productionUnitTokenContracts.length == 1);
        createProductionUnitTokenContract(15, 15, 15, 0.0000001 ether / 1000, 0.00000001 ether / 1000, 3, firstUnitStartTime + 1 days);
    }
    function createProductionUnit3Beta() public {
        require(productionUnitTokenContracts.length == 2);
        createProductionUnitTokenContract(20, 20, 20, 0.0000001 ether / 1000, 0.00000001 ether / 1000, 9, firstUnitStartTime + 2 days);
    }
    function createProductionUnitTokenContract(uint8 _entryFee, uint8 _transferFee, uint8 _exitFee, uint256 _tokenPriceInitial,
        uint256 _tokenPriceIncremental, uint256 _cookieProductionMultiplier, uint256 _startTime) internal {
        ProductionUnitToken newContract = new ProductionUnitToken(address(this),
            _entryFee, _transferFee, _exitFee, _tokenPriceInitial, _tokenPriceIncremental, _cookieProductionMultiplier, _startTime);
        productionUnitTokenContracts.push(newContract);
        productionUnitTokenContractAddresses[address(newContract)] = true;
        tokenContractStartTime.push(_startTime);
    }
    function productionUnitTokenContractCount() public view returns (uint) {
        return productionUnitTokenContracts.length;
    }
    function handleProductionIncrease(address player, uint256 amount) public payable {
        require(productionUnitTokenContractAddresses[msg.sender]);
        updatePlayersCookie(player);
        totalCookieProduction = SafeMath.add(totalCookieProduction, amount);
        cookieProduction[player] = SafeMath.add(cookieProduction[player], amount);
        if (msg.value > 0) {
            totalEtherCookieResearchPool += msg.value;
        }
    }
    function handleProductionDecrease(address player, uint256 amount) public payable {
        require(productionUnitTokenContractAddresses[msg.sender]);
        updatePlayersCookie(player);
        totalCookieProduction = SafeMath.sub(totalCookieProduction, amount);
        cookieProduction[player] = SafeMath.sub(cookieProduction[player], amount);
        if (msg.value > 0) {
            totalEtherCookieResearchPool += msg.value;
        }
    }
    function getState() public view returns (uint256, uint256, uint256, uint256, uint256, uint256, uint256) {
        return (totalCookieProduction, cookieProduction[msg.sender], totalSupply(), balanceOf(msg.sender),
            totalEtherCookieResearchPool, lastTotalCookieSaveTime, computeSellPrice());
    }
    function totalSupply() public constant returns(uint256) {
        return roughSupply + balanceOfTotalUnclaimedCookie();
    }
    function balanceOf(address player) public constant returns(uint256) {
        return cookieBalance[player] + balanceOfUnclaimedCookie(player);
    }
    function balanceOfTotalUnclaimedCookie() public constant returns(uint256) {
        if (lastTotalCookieSaveTime > 0 && lastTotalCookieSaveTime < block.timestamp) {
            return (totalCookieProduction * (block.timestamp - lastTotalCookieSaveTime));
        }
        return 0;
    }
    function balanceOfUnclaimedCookie(address player) internal constant returns (uint256) {
        uint256 lastSave = lastCookieSaveTime[player];
        if (lastSave > 0 && lastSave < block.timestamp) {
            return (cookieProduction[player] * (block.timestamp - lastSave));
        }
        return 0;
    }
    function transfer(address recipient, uint256 amount) public returns (bool) {
        updatePlayersCookie(msg.sender);
        require(amount <= cookieBalance[msg.sender]);
        cookieBalance[msg.sender] -= amount;
        cookieBalance[recipient] += amount;
        Transfer(msg.sender, recipient, amount);
        return true;
    }
    function transferFrom(address player, address recipient, uint256 amount) public returns (bool) {
        updatePlayersCookie(player);
        require(amount <= allowed[player][msg.sender] && amount <= cookieBalance[player]);
        cookieBalance[player] -= amount;
        cookieBalance[recipient] += amount;
        allowed[player][msg.sender] -= amount;
        Transfer(player, recipient, amount);
        return true;
    }
    function approve(address approvee, uint256 amount) public returns (bool){
        allowed[msg.sender][approvee] = amount;
        Approval(msg.sender, approvee, amount);
        return true;
    }
    function allowance(address player, address approvee) public constant returns(uint256){
        return allowed[player][approvee];
    }
    function updatePlayersCookie(address player) internal {
        uint256 cookieGain = balanceOfUnclaimedCookie(player);
        lastTotalCookieSaveTime = block.timestamp;
        lastCookieSaveTime[player] = block.timestamp;
        roughSupply += cookieGain;
        cookieBalance[player] += cookieGain;
    }
    // Sell all cookies, the eth earned is calculated by the proportion of cookies owned.
    // Selling of cookie is forbidden within one hour of new production unit launch.
    function sellAllCookies() public {
        updatePlayersCookie(msg.sender);
        uint256 sellPrice = computeSellPrice();
        require(sellPrice > 0);
        uint256 myCookies = cookieBalance[msg.sender];
        uint256 value = myCookies * sellPrice / (1 ether);
        cookieBalance[msg.sender] = 0;
        msg.sender.transfer(value);
    }
    // Compute sell price for 1 cookie, it is 0.5 when a new token contract is deployed,
    // and then goes up until it reaches the maximum sell price after 5 days.
    function computeSellPrice() public view returns (uint) {
        uint256 supply = totalSupply();
        if (supply == 0) {
            return 0;
        }
        uint index;
        uint lastTokenContractStartTime = now;
        while (index < tokenContractStartTime.length && tokenContractStartTime[index] < now) {
            lastTokenContractStartTime = tokenContractStartTime[index];
            index++;
        }
        if (now < lastTokenContractStartTime + 1 hours) {
            return 0;
        }
        uint timeToMaxValue = 2 days; // TODO: change to 5 days in main launch contract
        uint256 secondsPassed = now - lastTokenContractStartTime;
        secondsPassed = secondsPassed <= timeToMaxValue ? secondsPassed : timeToMaxValue;
        uint256 multiplier = 5000 + 5000 * secondsPassed / timeToMaxValue;
        return 1 ether * totalEtherCookieResearchPool / supply * multiplier / 10000;
    }
}

