pragma solidity ^0.6.12;
contract LPStaking is Ownable, ReentrancyGuard,Pausable {
    using SafeERC20 for IERC20;
    using SafeMath for uint;
    uint256 internal constant SHARE_MULTIPLIER = 1e18; // share multiplier to avert division underflow
    address public immutable assetContract; // the asset to stake
    address public constant ogsContract = 0x416947e6Fc78F158fd9B775fA846B72d768879c2;
    mapping (address => uint256) private _balances; // tracking staker's value
    mapping (address => uint256) internal _rewardBalance; // tracking staker's claimable reward tokens
    uint256 private _totalStaked; // track total staked value
    /// @dev initial block reward
    uint256 public BlockReward = 0;
    /// @dev round index mapping to accumulate share.
    mapping (uint => uint) private _accShares;
    /// @dev mark staker's highest settled round.
    mapping (address => uint) private _settledRounds;
    /// @dev a monotonic increasing round index, STARTS FROM 1
    uint256 private _currentRound = 1;
    // @dev last rewarded block
    uint256 private _lastRewardBlock = block.number;
    constructor(address assetContract_) public {
        require(assetContract_ != address(0), "constructor assetContract_ is zero address");
        assetContract = assetContract_; 
    }
    function setBlockReward(uint256 reward) external onlyOwner {
        // settle previous rewards
        updateReward();
        // set new block reward
        BlockReward = reward;
        // log
        emit BlockRewardSet(reward);
    }
    function pause() onlyOwner external { _pause(); }
    function unpause() onlyOwner external { _unpause(); }
    function deposit(uint256 amount) external nonReentrant whenNotPaused {
        require(amount > 0, "zero deposit");
        // settle previous rewards
        settleStaker(msg.sender);
        // modifiy
        _balances[msg.sender] += amount;
        _totalStaked += amount;
        // transfer asset from AssetContract
        IERC20(assetContract).safeTransferFrom(msg.sender, address(this), amount);
        // log
        emit Deposit(msg.sender, amount);
    }
    function claimRewards() external nonReentrant whenNotPaused {
        // settle previous rewards
        settleStaker(msg.sender);
        // reward balance modification
        uint amountReward = _rewardBalance[msg.sender];
        delete _rewardBalance[msg.sender]; // zero reward balance
        // mint reward to sender
        IOGSToken(ogsContract).mint(msg.sender, amountReward);
        // log
        emit OGSClaimed(msg.sender, amountReward);
    }
    function withdraw(uint256 amount) external nonReentrant {
        require(amount <= _balances[msg.sender], "balance exceeded");
        // settle previous rewards
        settleStaker(msg.sender);
        // modifiy
        _balances[msg.sender] -= amount;
        _totalStaked -= amount;
        // transfer assets back
        IERC20(assetContract).safeTransfer(msg.sender, amount);
        // log
        emit Withdraw(msg.sender, amount);
    }
    function settleStaker(address account) internal {
        // update reward snapshot
        updateReward();
        // settle this account
        uint accountCollateral = _balances[account];
        uint lastSettledRound = _settledRounds[account];
        uint newSettledRound = _currentRound - 1;
        // round rewards
        uint roundReward = _accShares[newSettledRound].sub(_accShares[lastSettledRound])
                                .mul(accountCollateral)
                                .div(SHARE_MULTIPLIER);  // remember to div by SHARE_MULTIPLIER    
        // update reward balance
        _rewardBalance[account] += roundReward;
        // mark new settled reward round
        _settledRounds[account] = newSettledRound;
    }
    function updateReward() internal {
        // skip round changing in the same block
        if (_lastRewardBlock == block.number) {
            return;
        }
        // postpone rewarding if there is none staker
        if (_totalStaked == 0) {
            return;
        }
        // settle reward share for [_lastRewardBlock, block.number]
        uint blocksToReward = block.number.sub(_lastRewardBlock);
        uint mintedReward = BlockReward.mul(blocksToReward);
        // reward share
        uint roundShare = mintedReward.mul(SHARE_MULTIPLIER)
                                        .div(_totalStaked);
        // mark block rewarded;
        _lastRewardBlock = block.number;
        // accumulate reward share
        _accShares[_currentRound] = roundShare.add(_accShares[_currentRound-1]); 
        // next round setting                                 
        _currentRound++;
    }
    function numStaked(address account) external view returns (uint256) { return _balances[account]; }
    function totalStaked() external view returns (uint256) { return _totalStaked; }
    function checkReward(address account) external view returns(uint256 rewards) {
        uint accountCollateral = _balances[account];
        uint lastSettledRound = _settledRounds[account];
        // reward = settled rewards + unsettled rewards + newMined rewards
        uint unsettledShare = _accShares[_currentRound-1].sub(_accShares[lastSettledRound]);
        uint newMinedShare;
        if (_totalStaked > 0) {
            uint blocksToReward = block.number.sub(_lastRewardBlock);
            uint mintedReward = BlockReward.mul(blocksToReward);
            // reward share
            newMinedShare = mintedReward.mul(SHARE_MULTIPLIER)
                                        .div(_totalStaked);
        }
        return _rewardBalance[account] + (unsettledShare + newMinedShare).mul(accountCollateral)
                                            .div(SHARE_MULTIPLIER);  // remember to div by SHARE_MULTIPLIER;
    }
     event Deposit(address account, uint256 amount);
     event Withdraw(address account, uint256 amount);
     event OGSClaimed(address account, uint256 amount);
     event BlockRewardSet(uint256 reward);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;
contract Staking is Ownable {
    using SafeERC20 for IERC20;
    IERC20 public rateToken;
    uint256 public constant FIXED_APY = 60; // 60% fixed APY
    uint256 public constant LOCK_DAYS = 7; // 7 days lockup period
    uint256 public constant SECONDS_IN_A_YEAR = 365 * 24 * 60 * 60;
    uint256 public constant DECIMALS_MULTIPLIER = 1e18;
    uint256 public totalStaked;
    struct StakerInfo {
        uint256 stakedAmount;
        uint256 lastClaimTimestamp;
        uint256 lockTimestamp;
    }
    mapping(address => StakerInfo) public stakers;
    constructor(IERC20 _rateToken) {
        rateToken = _rateToken;
    }
    function stake(uint256 amount) external {
        require(amount > 0, "Amount must be greater than 0");
        rateToken.safeTransferFrom(msg.sender, address(this), amount);
        StakerInfo storage staker = stakers[msg.sender];
        _updateRewards(msg.sender);
        staker.stakedAmount += amount;
        staker.lockTimestamp = block.timestamp + LOCK_DAYS * 1 days;
        totalStaked += amount;
    }
    function unstake(uint256 amount) external {
        StakerInfo storage staker = stakers[msg.sender];
        require(amount > 0 && staker.stakedAmount >= amount, "Invalid amount");
        require(block.timestamp >= staker.lockTimestamp,
            "Tokens are still locked");
        _updateRewards(msg.sender);
        // console.log(amount, 781);
        staker.stakedAmount -= amount;
        totalStaked -= amount;
        rateToken.safeTransfer(msg.sender, amount);
    }
    function claimRewards() external {
        _updateRewards(msg.sender);
    }
    function _updateRewards(address user) internal {
        StakerInfo storage staker = stakers[user];
        uint256 pendingRewards = _calculatePendingRewards(user);
        // console.log(pendingRewards, 999);
        if (pendingRewards > 0) {
            rateToken.safeTransfer(user, pendingRewards);
        }
        staker.lastClaimTimestamp = block.timestamp;
    }
    function _calculatePendingRewards(address user)
        internal
        view
        returns (uint256)
    {
        StakerInfo storage staker = stakers[user];
        uint256 timeSinceLastClaim = block.timestamp -
            staker.lastClaimTimestamp;
        uint256 rewardRate = (staker.stakedAmount *
            FIXED_APY *
            DECIMALS_MULTIPLIER) / (SECONDS_IN_A_YEAR * 100);
        return (timeSinceLastClaim * rewardRate) / DECIMALS_MULTIPLIER;
    }
}

pragma solidity ^0.8.0;
contract YELStaking is Ownable {
    using SafeERC20 for IERC20;
    struct UserInfo {
        uint256 amount; // How many tokens the user has provided.
        uint256 rewardDebt; // Reward debt. See explanation below.
        uint256 remainingYelTokenReward;  // YEL Tokens that weren't distributed for user per pool.
    }
    struct PoolInfo {
        IERC20 stakingToken; // Contract address of staked token
        uint256 stakingTokenTotalAmount; //Total amount of deposited tokens
        uint256 accYelPerShare; // Accumulated YEL per share, times 1e12. See below.
        uint32 lastRewardTime; // Last timestamp number that YEL distribution occurs.
        uint16 allocPoint; // How many allocation points assigned to this pool. YEL to distribute per second.
    }
    IERC20 immutable public yel; // The YEL token
    uint256 public yelPerSecond; // YEL tokens vested per second.
    PoolInfo[] public poolInfo; // Info of each pool.
    mapping(uint256 => mapping(address => UserInfo)) public userInfo; // Info of each user that stakes tokens.
    uint256 public totalAllocPoint = 0; // Total allocation points. Must be the sum of all allocation points in all pools.
    uint32 immutable public startTime; // The timestamp when YEL farming starts.
    uint32 public endTime; // Time on which the reward calculation should end
    event Deposit(address indexed user, uint256 indexed pid, uint256 amount);
    event Withdraw(address indexed user, uint256 indexed pid, uint256 amount);
    event EmergencyWithdraw(address indexed user, uint256 indexed pid, uint256 amount);
    constructor(IERC20 _yel,
        uint256 _yelPerSecond,
        uint32 _startTime) {
        yel = _yel;
        yelPerSecond = _yelPerSecond;
        startTime = _startTime;
        endTime = _startTime + 7 days;
    }
    function changeEndTime(uint32 addSeconds) external onlyOwner {
        endTime += addSeconds;
    }
    function setYelPerSecond(uint256 _yelPerSecond,  bool _withUpdate) external onlyOwner {
        if (_withUpdate) {
            massUpdatePools();
        }
        yelPerSecond= _yelPerSecond;
    }
    function poolLength() external view returns (uint256) {
        return poolInfo.length;
    }
    function add(uint16 _allocPoint,
        IERC20 _stakingToken,
        bool _withUpdate) external onlyOwner {
        if (_withUpdate) {
            massUpdatePools();
        }
        uint256 lastRewardTime =
            block.timestamp > startTime ? block.timestamp : startTime;
        totalAllocPoint +=_allocPoint;
        poolInfo.push(PoolInfo({
                stakingToken: _stakingToken,
                stakingTokenTotalAmount: 0,
                allocPoint: _allocPoint,
                lastRewardTime: uint32(lastRewardTime),
                accYelPerShare: 0
            }));
    }
    function set(uint256 _pid,
        uint16 _allocPoint,
        bool _withUpdate) external onlyOwner {
        if (_withUpdate) {
            massUpdatePools();
        }
        totalAllocPoint = totalAllocPoint - poolInfo[_pid].allocPoint + _allocPoint;
        poolInfo[_pid].allocPoint = _allocPoint;
    }
    function getMultiplier(uint256 _from, uint256 _to)
        public
        view
        returns (uint256)
    {
        _from = _from > startTime ? _from : startTime;
        if (_from > endTime || _to < startTime) {
            return 0;
        }
        if (_to > endTime) {
            return endTime - _from;
        }
        return _to - _from;
    }
    function pendingYel(uint256 _pid, address _user)
        external
        view
        returns (uint256)
    {
        PoolInfo storage pool = poolInfo[_pid];
        UserInfo storage user = userInfo[_pid][_user];
        uint256 accYelPerShare = pool.accYelPerShare;
        if (block.timestamp > pool.lastRewardTime && pool.stakingTokenTotalAmount != 0) {
            uint256 multiplier =
                getMultiplier(pool.lastRewardTime, block.timestamp);
            uint256 yelReward =
                multiplier * yelPerSecond * pool.allocPoint / totalAllocPoint;
            accYelPerShare += yelReward * 1e12 / pool.stakingTokenTotalAmount;
        }
        return user.amount * accYelPerShare / 1e12 - user.rewardDebt + user.remainingYelTokenReward;
    }
    function massUpdatePools() public {
        uint256 length = poolInfo.length;
        for (uint256 pid = 0; pid < length; ++pid) {
            updatePool(pid);
        }
    }
    function updatePool(uint256 _pid) public {
        PoolInfo storage pool = poolInfo[_pid];
        if (block.timestamp <= pool.lastRewardTime) {
            return;
        }
        if (pool.stakingTokenTotalAmount == 0) {
            pool.lastRewardTime = uint32(block.timestamp);
            return;
        }
        uint256 multiplier = getMultiplier(pool.lastRewardTime, block.timestamp);
        uint256 yelReward =
            multiplier * yelPerSecond * pool.allocPoint / totalAllocPoint;
        pool.accYelPerShare += yelReward * 1e12 / pool.stakingTokenTotalAmount;
        pool.lastRewardTime = uint32(block.timestamp);
    }
    function deposit(uint256 _pid, uint256 _amount) public {
        PoolInfo storage pool = poolInfo[_pid];
        UserInfo storage user = userInfo[_pid][msg.sender];
        updatePool(_pid);
        if (user.amount > 0) {
            uint256 pending =
                user.amount * pool.accYelPerShare / 1e12 - user.rewardDebt + user.remainingYelTokenReward;
            user.remainingYelTokenReward = safeRewardTransfer(msg.sender, pending);
        }
        pool.stakingToken.safeTransferFrom(address(msg.sender),
            address(this),
            _amount);
        user.amount += _amount;
        pool.stakingTokenTotalAmount += _amount;
        user.rewardDebt = user.amount * pool.accYelPerShare / 1e12;
        emit Deposit(msg.sender, _pid, _amount);
    }
    function withdraw(uint256 _pid, uint256 _amount) public {
        PoolInfo storage pool = poolInfo[_pid];
        UserInfo storage user = userInfo[_pid][msg.sender];
        require(user.amount >= _amount, "YELStaking: you do not have enough tokens to complete this operation");
        updatePool(_pid);
        uint256 pending =
            user.amount * pool.accYelPerShare / 1e12 - user.rewardDebt + user.remainingYelTokenReward;
        user.remainingYelTokenReward = safeRewardTransfer(msg.sender, pending);
        user.amount -= _amount;
        pool.stakingTokenTotalAmount -= _amount;
        user.rewardDebt = user.amount * pool.accYelPerShare / 1e12;
        pool.stakingToken.safeTransfer(address(msg.sender), _amount);
        emit Withdraw(msg.sender, _pid, _amount);
    }
    function emergencyWithdraw(uint256 _pid) public {
        PoolInfo storage pool = poolInfo[_pid];
        UserInfo storage user = userInfo[_pid][msg.sender];
        uint256 userAmount = user.amount;
        pool.stakingTokenTotalAmount -= userAmount;
        delete userInfo[_pid][msg.sender];
        pool.stakingToken.safeTransfer(address(msg.sender), userAmount);
        emit EmergencyWithdraw(msg.sender, _pid, userAmount);
    }
    function safeRewardTransfer(address _to, uint256 _amount) internal returns(uint256) {
        uint256 yelTokenBalance = yel.balanceOf(address(this));
        if (yelTokenBalance == 0) { //save some gas fee
            return _amount;
        }
        if (_amount > yelTokenBalance) { //save some gas fee
            yel.safeTransfer(_to, yelTokenBalance);
            return _amount - yelTokenBalance;
        }
        yel.safeTransfer(_to, _amount);
        return 0;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;
contract AlchemyPowerCraftStaking is Ownable {
    using SafeERC20 for IERC20;
    struct UserInfo {
        uint256 balance;
        uint256 reward;
        uint256 rewardPerTokenPaid;
        uint256 paidOut;
    }
    IERC20 public craft;
    IAlchemyPower public alchemyPower;
    ITimeProvider public immutable timeProvider;
    uint256 public totalBalance;
    uint256 public rewardPerTokenStored;
    uint256 public lastUpdateTime;
    uint256 public constant tokensPerSecond = .003e18;
    mapping (address => UserInfo) public userInfos;
    event CraftStaked(address indexed account, uint256 amount);
    event CraftUnstaked(address indexed account, uint256 amount);
    constructor(IAlchemyPower alchemyPower_, IERC20 craft_, ITimeProvider timeProvider_) {
        alchemyPower = alchemyPower_;
        craft = craft_;
        timeProvider = timeProvider_;
    }
    function _rewardPerToken() public view returns (uint256) {
        if (totalBalance == 0)
            return rewardPerTokenStored;
        return rewardPerTokenStored + (timeProvider.getTimestamp() - lastUpdateTime) * tokensPerSecond * 1e18 / totalBalance;
    }
    function pendingAlchemyPower(address account) public view returns (uint256) {
        UserInfo storage userInfo = userInfos[account];
        return userInfo.balance * (_rewardPerToken() - userInfo.rewardPerTokenPaid) / 1e18 + userInfo.reward;
    }
    function _updateReward(address account) private {
        rewardPerTokenStored = _rewardPerToken();
        lastUpdateTime = timeProvider.getTimestamp();
        if (account != address(0)) {
            UserInfo storage userInfo = userInfos[account];
            userInfo.reward = pendingAlchemyPower(account);
            userInfo.rewardPerTokenPaid = rewardPerTokenStored;
        }
    }
    function stake(uint256 amount) external {
        require(amount > 0, "cannot stake 0");
        _updateReward(msg.sender);
        totalBalance += amount;
        userInfos[msg.sender].balance += amount;
        craft.safeTransferFrom(msg.sender, address(this), amount);
        emit CraftStaked(msg.sender, amount);
    }
    function unstake() external {
        UserInfo storage userInfo = userInfos[msg.sender];
        uint256 amount = userInfo.balance;
        require(amount > 0, "nothing to unstake");
        _updateReward(msg.sender);
        totalBalance -= amount;
        userInfo.balance -= amount;
        userInfo.reward = 0;
        uint256 paidOut = userInfo.paidOut;
        userInfo.paidOut = 0;
        alchemyPower.burn(msg.sender, paidOut);
        craft.safeTransfer(msg.sender, amount);
        emit CraftUnstaked(msg.sender, amount);
    }
    function claimAlchemyPower() external {
        _updateReward(msg.sender);
        UserInfo storage userInfo = userInfos[msg.sender];
        uint256 reward = userInfo.reward;
        require(reward > 0, "nothing to claim");
        userInfo.reward = 0;
        userInfo.paidOut += reward;
        alchemyPower.mint(msg.sender, reward);
    }
}

