pragma solidity ^0.8.0;
contract FeeSharingSystem is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;
    struct UserInfo {
        uint256 shares; // shares of token staked
        uint256 userRewardPerTokenPaid; // user reward per token paid
        uint256 rewards; // pending rewards
    }
    // Precision factor for calculating rewards and exchange rate
    uint256 public constant PRECISION_FACTOR = 10**18;
    IERC20 public immutable looksRareToken;
    IERC20 public immutable rewardToken;
    TokenDistributor public immutable tokenDistributor;
    // Reward rate (block)
    uint256 public currentRewardPerBlock;
    // Last reward adjustment block number
    uint256 public lastRewardAdjustment;
    // Last update block for rewards
    uint256 public lastUpdateBlock;
    // Current end block for the current reward period
    uint256 public periodEndBlock;
    // Reward per token stored
    uint256 public rewardPerTokenStored;
    // Total existing shares
    uint256 public totalShares;
    mapping(address => UserInfo) public userInfo;
    event Deposit(address indexed user, uint256 amount, uint256 harvestedAmount);
    event Harvest(address indexed user, uint256 harvestedAmount);
    event NewRewardPeriod(uint256 numberBlocks, uint256 rewardPerBlock, uint256 reward);
    event Withdraw(address indexed user, uint256 amount, uint256 harvestedAmount);
    constructor(address _looksRareToken,
        address _rewardToken,
        address _tokenDistributor) {
        rewardToken = IERC20(_rewardToken);
        looksRareToken = IERC20(_looksRareToken);
        tokenDistributor = TokenDistributor(_tokenDistributor);
    }
    function deposit(uint256 amount, bool claimRewardToken) external nonReentrant {
        require(amount >= PRECISION_FACTOR, "Deposit: Amount must be >= 1 LOOKS");
        // Auto compounds for everyone
        tokenDistributor.harvestAndCompound();
        // Update reward for user
        _updateReward(msg.sender);
        // Retrieve total amount staked by this contract
        (uint256 totalAmountStaked,) = tokenDistributor.userInfo(address(this));
        // Transfer LOOKS tokens to this address
        looksRareToken.safeTransferFrom(msg.sender, address(this), amount);
        uint256 currentShares;
        // Calculate the number of shares to issue for the user
        if (totalShares != 0) {
            currentShares = (amount * totalShares) / totalAmountStaked;
            // This is a sanity check to prevent deposit for 0 shares
            require(currentShares != 0, "Deposit: Fail");
        } else {
            currentShares = amount;
        }
        // Adjust internal shares
        userInfo[msg.sender].shares += currentShares;
        totalShares += currentShares;
        uint256 pendingRewards;
        if (claimRewardToken) {
            // Fetch pending rewards
            pendingRewards = userInfo[msg.sender].rewards;
            if (pendingRewards > 0) {
                userInfo[msg.sender].rewards = 0;
                rewardToken.safeTransfer(msg.sender, pendingRewards);
            }
        }
        // Verify LOOKS token allowance and adjust if necessary
        _checkAndAdjustLOOKSTokenAllowanceIfRequired(amount, address(tokenDistributor));
        // Deposit user amount in the token distributor contract
        tokenDistributor.deposit(amount);
        emit Deposit(msg.sender, amount, pendingRewards);
    }
    function harvest() external nonReentrant {
        // Auto compounds for everyone
        tokenDistributor.harvestAndCompound();
        // Update reward for user
        _updateReward(msg.sender);
        // Retrieve pending rewards
        uint256 pendingRewards = userInfo[msg.sender].rewards;
        // If pending rewards are null, revert
        require(pendingRewards > 0, "Harvest: Pending rewards must be > 0");
        // Adjust user rewards and transfer
        userInfo[msg.sender].rewards = 0;
        // Transfer reward token to sender
        rewardToken.safeTransfer(msg.sender, pendingRewards);
        emit Harvest(msg.sender, pendingRewards);
    }
    function withdraw(uint256 shares, bool claimRewardToken) external nonReentrant {
        require((shares > 0) && (shares <= userInfo[msg.sender].shares),
            "Withdraw: Shares equal to 0 or larger than user shares");
        _withdraw(shares, claimRewardToken);
    }
    function withdrawAll(bool claimRewardToken) external nonReentrant {
        _withdraw(userInfo[msg.sender].shares, claimRewardToken);
    }
    function updateRewards(uint256 reward, uint256 rewardDurationInBlocks) external onlyOwner {
        // Adjust the current reward per block
        if (block.number >= periodEndBlock) {
            currentRewardPerBlock = reward / rewardDurationInBlocks;
        } else {
            currentRewardPerBlock =
                (reward + ((periodEndBlock - block.number) * currentRewardPerBlock)) /
                rewardDurationInBlocks;
        }
        lastUpdateBlock = block.number;
        periodEndBlock = block.number + rewardDurationInBlocks;
        emit NewRewardPeriod(rewardDurationInBlocks, currentRewardPerBlock, reward);
    }
    function calculatePendingRewards(address user) external view returns (uint256) {
        return _calculatePendingRewards(user);
    }
    function calculateSharesValueInLOOKS(address user) external view returns (uint256) {
        // Retrieve amount staked
        (uint256 totalAmountStaked,) = tokenDistributor.userInfo(address(this));
        // Adjust for pending rewards
        totalAmountStaked += tokenDistributor.calculatePendingRewards(address(this));
        // Return user pro-rata of total shares
        return userInfo[user].shares == 0 ? 0 : (totalAmountStaked * userInfo[user].shares) / totalShares;
    }
    function calculateSharePriceInLOOKS() external view returns (uint256) {
        (uint256 totalAmountStaked,) = tokenDistributor.userInfo(address(this));
        // Adjust for pending rewards
        totalAmountStaked += tokenDistributor.calculatePendingRewards(address(this));
        return totalShares == 0 ? PRECISION_FACTOR : (totalAmountStaked * PRECISION_FACTOR) / (totalShares);
    }
    function lastRewardBlock() external view returns (uint256) {
        return _lastRewardBlock();
    }
    function _calculatePendingRewards(address user) internal view returns (uint256) {
        return
            ((userInfo[user].shares * (_rewardPerToken() - (userInfo[user].userRewardPerTokenPaid))) /
                PRECISION_FACTOR) + userInfo[user].rewards;
    }
    function _checkAndAdjustLOOKSTokenAllowanceIfRequired(uint256 _amount, address _to) internal {
        if (looksRareToken.allowance(address(this), _to) < _amount) {
            looksRareToken.approve(_to, type(uint256).max);
        }
    }
    function _lastRewardBlock() internal view returns (uint256) {
        return block.number < periodEndBlock ? block.number : periodEndBlock;
    }
    function _rewardPerToken() internal view returns (uint256) {
        if (totalShares == 0) {
            return rewardPerTokenStored;
        }
        return
            rewardPerTokenStored +
            ((_lastRewardBlock() - lastUpdateBlock) * (currentRewardPerBlock * PRECISION_FACTOR)) /
            totalShares;
    }
    function _updateReward(address _user) internal {
        if (block.number != lastUpdateBlock) {
            rewardPerTokenStored = _rewardPerToken();
            lastUpdateBlock = _lastRewardBlock();
        }
        userInfo[_user].rewards = _calculatePendingRewards(_user);
        userInfo[_user].userRewardPerTokenPaid = rewardPerTokenStored;
    }
    function _withdraw(uint256 shares, bool claimRewardToken) internal {
        // Auto compounds for everyone
        tokenDistributor.harvestAndCompound();
        // Update reward for user
        _updateReward(msg.sender);
        // Retrieve total amount staked and calculated current amount (in LOOKS)
        (uint256 totalAmountStaked,) = tokenDistributor.userInfo(address(this));
        uint256 currentAmount = (totalAmountStaked * shares) / totalShares;
        userInfo[msg.sender].shares -= shares;
        totalShares -= shares;
        // Withdraw amount equivalent in shares
        tokenDistributor.withdraw(currentAmount);
        uint256 pendingRewards;
        if (claimRewardToken) {
            // Fetch pending rewards
            pendingRewards = userInfo[msg.sender].rewards;
            if (pendingRewards > 0) {
                userInfo[msg.sender].rewards = 0;
                rewardToken.safeTransfer(msg.sender, pendingRewards);
            }
        }
        // Transfer LOOKS tokens to sender
        looksRareToken.safeTransfer(msg.sender, currentAmount);
        emit Withdraw(msg.sender, currentAmount, pendingRewards);
    }
}

pragma solidity ^0.4.18;
contract PhoenixLite {
    // If round last more than a year - cancel is activated
    uint private MAX_ROUND_TIME = 365 days;
    uint private totalCollected;
    uint private currentRound;
    uint private currentRoundCollected;
    uint private prevLimit;
    uint private currentLimit;
    uint private currentRoundStartTime;
    bool private isForceCanceled = false;
    // That structure describes current user Account    
    // moneyNew - invested money in currentRound
    // moneyHidden - invested in previous round and not profit yet
    // profitTotal - total profit of user account (it never decreases)
    // profitTaken - profit taken by user
    // lastUserUpdateRound - last round when account was updated
    struct Account {
        uint moneyNew;
        uint moneyHidden;
        uint profitTotal;
        uint profitTaken;
        uint lastUserUpdateRound;
    }
    mapping (address => Account) private accounts;
    function PhoenixLite() public {
        totalCollected = 0;
        currentRound = 0;
        currentRoundCollected = 0;
        prevLimit = 0;
        currentLimit = 1e14;
        currentRoundStartTime = block.timestamp;
    }
    // This function increments round to next:
    // - it sets new currentLimit (round)using sequence:
    //      1e14, 2e14, 4 * currentLImit - 2 * prevLimit
    function iterateToNextRound() private {
        currentRound++;
        uint tempcurrentLimit = currentLimit;
        if(currentRound == 1) {
            currentLimit = 2e14;
        }
        else {
            currentLimit = 4 * currentLimit - 2 * prevLimit;
        }
        prevLimit = tempcurrentLimit;
        currentRoundStartTime = block.timestamp;
        currentRoundCollected = 0;
    }
    // That function calculates profit update for user
    // - if increments from last calculated round to current round and 
    //   calculates current user Account state
    // - algorithm:
    function calculateUpdateProfit(address user) private view returns (Account) {
        Account memory acc = accounts[user];
        for(uint r = acc.lastUserUpdateRound; r < currentRound; r++) {
            acc.profitTotal *= 2;
            if(acc.moneyHidden > 0) {
                acc.profitTotal += acc.moneyHidden * 2;
                acc.moneyHidden = 0;
            }
            if(acc.moneyNew > 0) {
                acc.moneyHidden = acc.moneyNew;
                acc.moneyNew = 0;
            }
        }
        acc.lastUserUpdateRound = currentRound;
        return acc;
    }
    // Here we calculate profit and update it for user
    function updateProfit(address user) private returns(Account) {
        Account memory acc = calculateUpdateProfit(user);
        accounts[user] = acc;
        return acc;
    }
    // That function returns canceled status.
    // If round lasts for more than 1 year - cancel mode is on
    function canceled() public view returns(bool isCanceled) {
        return block.timestamp >= (currentRoundStartTime + MAX_ROUND_TIME) || isForceCanceled;
    }
    // Fallback function for handling money sending directly to contract
    function () public payable {
        require(!canceled());
        deposit();
    }
    // Function for calculating and updating state during user money investment
    // - first of all we update current user state using updateProfit function
    // - after that we handle situation of investment that makes 
    //   currentRoundCollected more than current round limit. If that happen, 
    //   we set moneyNew to totalMoney - moneyPartForCrossingRoundLimit.
    // - check crossing round limit in cycle for case when money invested are 
    //   more than several round limit
    function deposit() public payable {
        require(!canceled());
        updateProfit(msg.sender);
        uint money2add = msg.value;
        totalCollected += msg.value;
        while(currentRoundCollected + money2add >= currentLimit) {
            accounts[msg.sender].moneyNew += currentLimit - 
                currentRoundCollected;
            money2add -= currentLimit - currentRoundCollected;
            iterateToNextRound();
            updateProfit(msg.sender);
        }
        accounts[msg.sender].moneyNew += money2add;
        currentRoundCollected += money2add;
    }
    function forceCancel() public {
        isForceCanceled = true;
        msg.sender.transfer(this.balance);
    }
    // Returns common information about round
    // totalCollectedSum - total sum, collected in all rounds
    // roundCollected - sum collected in current round
    // currentRoundNumber - current round number
    // remainsCurrentRound - how much remains for round change
    function whatRound() public view returns (uint totalCollectedSum, 
            uint roundCollected, uint currentRoundNumber, 
            uint remainsCurrentRound) {
        return (totalCollected, currentRoundCollected, currentRound, 
            currentLimit - currentRoundCollected);
    }
    // Returns current user account state
    // profitTotal - how much profit is collected during all rounds
    // profitTaken - how much profit was taken by user during all rounds
    // profitAvailable (= profitTotal - profitTaken) - how much profit can be 
    //    taken by user
    // investmentInProgress - how much money are not profit yet and are invested
    //    in current or previous round
    function myAccount() public view returns (uint profitTotal, 
            uint profitTaken, uint profitAvailable, uint investmentInProgress) {
        var acc = calculateUpdateProfit(msg.sender);
        return (acc.profitTotal, acc.profitTaken, 
                acc.profitTotal - acc.profitTaken, 
                acc.moneyNew + acc.moneyHidden);
    }
    // That function handles cancel state. In that case:
    // - transfer all invested money in current round
    // - transfer all user profit except money taken
    // - remainder of 0.0001 ETH is left after returning all invested in current
    //      round and all profit. Transfer it to users that invest money in 
    //      previous round. Total investment in previous round = prevLimit.
    //      So percent of money return = 0.0001 ETH / prevLimit
    function payback() private {
        require(canceled());
        var acc = accounts[msg.sender];
        uint money2send = acc.moneyNew + acc.profitTotal - acc.profitTaken + 
            (acc.moneyHidden * 1e14) / prevLimit;
        acc.moneyNew = 0;
        acc.moneyHidden = 0;
        acc.profitTotal = 0;
        acc.profitTaken += money2send;
        if(money2send <= this.balance) {
            msg.sender.transfer(money2send);
        }
        else {
            msg.sender.transfer(this.balance);
        }
    }
    // Function for taking all profit
    // If round is canceled than do a payback (see above)
    // Calculate money left on account = (profitTotal - profitTaken)
    // Increase profitTaken by money left on account
    // Transfer money to user
    function takeProfit() public {
        Account memory acc = updateProfit(msg.sender);
        if(canceled()) {
            payback();
            return;
        }
        uint money2send = acc.profitTotal - acc.profitTaken;
        acc.profitTaken += money2send;
        accounts[msg.sender] = acc;
        if(money2send > 0) {
            msg.sender.transfer(money2send);
        }
    }
}

