pragma solidity ^0.8.0;
contract CrackVault is ERC20, Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;
    // Side-Profit tracker
    struct UserInfo {
        bool exist;
        uint256 shares;
        uint256 profitAmount;
    }
    mapping(address => UserInfo) public userInfo;
    address[] public userList; // list of all addresses deposited
    uint256 internal profitToBeDistributed;
    // The strategy currently in use by the vault.
    IStrategy public strategy;
    constructor (IStrategy _strategy,
        string memory _name,
        string memory _symbol) ERC20(_name,
        _symbol) {
        strategy = _strategy;
    }
    function staked() public view returns (IERC20) {
        return IERC20(strategy.stakedToken());
    }
    function profit() public view returns (IERC20) {
      return IERC20(strategy.sideProfitToken());
    }
    function balance() public view returns (uint) {
        return (staked().balanceOf(address(this))) + (IStrategy(strategy).totalBalanceOfStaked());
    }
    function updatePendingProfit() external {
        _updateUserList();
    }
    function addProfit(uint256 _profitToBeDistributed) external {
        require(msg.sender == address(strategy), "not strategy");
        require(_profitToBeDistributed > 0, "No profits");
        profitToBeDistributed += _profitToBeDistributed;
    }
    function _updateUserList() internal {
        if (profitToBeDistributed > 0)
        {
            uint256 totalCrackSupply = totalSupply();
            for (uint8 i = 0; i < userList.length; i++) {
                // check if user should be removed
                while (!userInfo[userList[i]].exist) {
                    // If last entry in array, pop
                    if (i == (userList.length-1)) {
                        userList.pop();
                        return;
                    } else {
                        // swap with last item and pop
                        userList[i] = userList[userList.length - 1];
                        userList.pop();
                    }
                }
                // calculate user's share of profit
                userInfo[userList[i]].profitAmount += FullMath.mulDiv(profitToBeDistributed, userInfo[userList[i]].shares, totalCrackSupply);
            }
            profitToBeDistributed = 0;
        }
    }
    function claimProfit() public {
        require(userInfo[msg.sender].exist, "No profits");
        uint256 profitAmount = userInfo[msg.sender].profitAmount;
        if (profitAmount > 0) {
            userInfo[msg.sender].profitAmount = 0;
            profit().safeTransfer(msg.sender, profitAmount);
        }
    }
    function getPricePerFullShare() public view returns (uint256) {
        return totalSupply() == 0 ? 1e18 : ((balance() * 1e18) / totalSupply());
    }
    function depositAll() external {
        deposit(staked().balanceOf(msg.sender));
    }
    function deposit(uint _amount) public nonReentrant {
        strategy.beforeDeposit();
        _updateUserList();
        uint256 _pool = balance();
        staked().safeTransferFrom(msg.sender, address(this), _amount);
        earn();
        uint256 _after = balance();
        _amount = _after - _pool; // Additional check for deflationary tokens
        uint256 shares = 0;
        if (totalSupply() == 0) {
            shares = _amount;
        } else {
            shares = ((_amount * totalSupply()) / _pool);
        }
        // Check if we need to add user to userList
        if (!userInfo[msg.sender].exist) {
            userInfo[msg.sender].exist = true;
            userList.push(msg.sender);
        }
        userInfo[msg.sender].shares += shares;
        _mint(msg.sender, shares);
    }
    function earn() public {
        uint _bal = staked().balanceOf(address(this));
        staked().safeTransfer(address(strategy), _bal);
        strategy.deposit();
    }
    function withdrawAll() external {
        withdraw(balanceOf(msg.sender));
    }
    function withdraw(uint256 _shares) public {
        _updateUserList();
        uint256 r = FullMath.mulDiv(balance(), _shares, totalSupply());
        _burn(msg.sender, _shares);
        uint b = staked().balanceOf(address(this));
        if (b < r) {
            uint _withdraw = r - b;
            strategy.withdraw(_withdraw);
            uint _after = staked().balanceOf(address(this));
            uint _diff = _after - b;
            if (_diff < _withdraw) {
                r = b + _diff;
            }
        }
        staked().safeTransfer(msg.sender, r);
        claimProfit();
        userInfo[msg.sender].shares -= _shares;
        if (userInfo[msg.sender].shares == 0) {
            userInfo[msg.sender].exist = false;
        }
    }
    function setStrategy(address _strategy) external onlyOwner {
        strategy = IStrategy(_strategy);
    }
    function inCaseTokensGetStuck(address _token) external onlyOwner {
        require(_token != address(staked()), "!token");
        uint256 amount = IERC20(_token).balanceOf(address(this));
        IERC20(_token).safeTransfer(msg.sender, amount);
    }
}

contract Level is IAttribute, ERC20 {
  // Not sure the URI is actually needed? What are we using this for?
  uint256 public uri = 10;
  // This needs to be exploded out into it's own ERC20
  uint256 public currentXP = 100;
  uint256 public currentLvl = 1;
  uint256 public lastTime = 0;
  uint256 public maxXPDaily = 10;
  uint256[] public requiredXp;
  uint256 private _dripRate;
  uint256 private _maxAmount;
  IERC20 private _requiredToken;
  uint256 private constant _BASE = 10000;
  mapping(address => bool) private _senderWhitelist;
  mapping(address => uint256) private _balances;
  // EXP calculations per level are handled off-chain, and updated
  constructor(uint256[] memory _requiredXp,
    IERC20 requiredToken_,
    uint256 maxAmount_,
    uint256 dripRate_) ERC20("Level", "LVL") {
    _dripRate = dripRate_;
    lastTime = block.timestamp;
    requiredXp = _requiredXp;
    _maxAmount = maxAmount_;
    _requiredToken = requiredToken_;
  }
  function stake(uint256 amount) external {
    _accrueXP();
    require(_balances[msg.sender] + amount <= _maxAmount,
      "Sorry that exceeds the max staking amount");
    _balances[msg.sender] += amount;
    _requiredToken.transferFrom(msg.sender, address(this), amount);
  }
  function unstake(uint256 amount) external {
    _accrueXP();
    _requiredToken.transferFrom(address(this), msg.sender, amount);
    _balances[msg.sender] -= amount;
  }
  function getURI() external view override returns (uint256) {
    return uri;
  }
  function attribute() external view override returns (uint256) {
    return currentLvl;
  }
  function adjustAttribute(uint256 newAttribute) external override {
    _accrueXP();
  }
  // Obviously needs permissions
  // Need to make it so that we can make this append only
  function setXPRequiremenets(uint256[] memory _requiredXp) external {
    requiredXp = _requiredXp;
  }
  function setSpecificLevel(uint256 newRequirement, uint256 index) external {
    requiredXp[index] = newRequirement;
  }
  function _accrueXP() internal {
    uint256 timePassed = block.timestamp - lastTime;
    // (Balance of sender * total time passed sincce last accrual in blocks * drip rate) /
    currentXP +=
      (_balances[msg.sender] * (timePassed * _dripRate) * _BASE) /
      (_maxAmount * _BASE);
    // I think this accounts for the lost precision but double-check plz
    lastTime = block.timestamp;
  }
  // Need to tweak this; as this stands if we change XP requirements the level will be maintained
  function level() public {
    _accrueXP();
    // Should revert if the player doesn't have sufficient XP
    currentXP -= requiredXp[currentLvl];
    currentLvl += 1;
  }
  function getLevel() public {}
  function _beforeTokenTransfer(address from,
    address,
    uint256) internal view override {
    require(_senderWhitelist[from] == true, "Sender must be whitelisted");
  }
}

