pragma solidity ^0.8.24;
contract EpochFarm {
    struct PoolInfo {
        IToken stakeToken;
        uint256 emissionPerEpoch;
        uint256 lastEpoch;
        uint256 accPerShare;
        uint256 totalStaked;
    }

    struct Position {
        uint256 amount;
        uint256 rewardDebt;
    }

    uint256 public constant EPOCH_BLOCKS = 7200;
    uint256 private constant PREC = 1e12;

    IToken public immutable rewardToken;
    address public immutable admin;

    PoolInfo[] public pools;
    mapping(uint256 => mapping(address => Position)) public positions;

    event PoolAdded(uint256 indexed pid, address stakeToken, uint256 emissionPerEpoch);
    event Staked(uint256 indexed pid, address indexed user, uint256 amount);
    event Unstaked(uint256 indexed pid, address indexed user, uint256 amount);
    event Harvested(uint256 indexed pid, address indexed user, uint256 amount);

    constructor(IToken _rewardToken) {
        rewardToken = _rewardToken;
        admin = msg.sender;
    }

    function currentEpoch() public view returns (uint256) {
        return block.number / EPOCH_BLOCKS;
    }

    function poolCount() external view returns (uint256) {
        return pools.length;
    }

    function addPool(IToken stakeToken, uint256 emissionPerEpoch) external returns (uint256 pid) {
        require(msg.sender == admin, "admin only");
        pid = pools.length;
        pools.push(
            PoolInfo({
                stakeToken: stakeToken,
                emissionPerEpoch: emissionPerEpoch,
                lastEpoch: currentEpoch(),
                accPerShare: 0,
                totalStaked: 0
            })
        );
        emit PoolAdded(pid, address(stakeToken), emissionPerEpoch);
    }

    // Settlement: credit every epoch elapsed since the pool was last checkpointed.
    function _checkpoint(uint256 pid) internal {
        PoolInfo storage p = pools[pid];
        uint256 epoch = currentEpoch();
        if (epoch <= p.lastEpoch) {
            return;
        }
        uint256 epochsElapsed = epoch - p.lastEpoch;
        p.lastEpoch = epoch;
        if (p.totalStaked == 0) {
            return;
        }
        p.accPerShare += (epochsElapsed * p.emissionPerEpoch * PREC) / p.totalStaked;
    }

    function _send(address to, uint256 amount) private {
        require(rewardToken.transfer(to, amount), "reward transfer");
    }

    function stake(uint256 pid, uint256 amount) external {
        require(amount != 0, "zero");
        _checkpoint(pid);
        PoolInfo storage p = pools[pid];
        Position storage pos = positions[pid][msg.sender];
        uint256 owed = (pos.amount * p.accPerShare) / PREC - pos.rewardDebt;

        pos.amount += amount;
        p.totalStaked += amount;
        pos.rewardDebt = (pos.amount * p.accPerShare) / PREC;

        require(p.stakeToken.transferFrom(msg.sender, address(this), amount), "stake transfer");
        if (owed != 0) {
            _send(msg.sender, owed);
        }
        emit Staked(pid, msg.sender, amount);
    }

    function unstake(uint256 pid, uint256 amount) external {
        Position storage pos = positions[pid][msg.sender];
        require(amount != 0 && pos.amount >= amount, "bad amount");
        _checkpoint(pid);
        PoolInfo storage p = pools[pid];
        uint256 owed = (pos.amount * p.accPerShare) / PREC - pos.rewardDebt;

        pos.amount -= amount;
        p.totalStaked -= amount;
        pos.rewardDebt = (pos.amount * p.accPerShare) / PREC;

        require(p.stakeToken.transfer(msg.sender, amount), "stake return");
        if (owed != 0) {
            _send(msg.sender, owed);
        }
        emit Unstaked(pid, msg.sender, amount);
    }

    function harvest(uint256 pid) external {
        _checkpoint(pid);
        PoolInfo storage p = pools[pid];
        Position storage pos = positions[pid][msg.sender];
        uint256 owed = (pos.amount * p.accPerShare) / PREC - pos.rewardDebt;

        pos.rewardDebt = (pos.amount * p.accPerShare) / PREC;
        if (owed != 0) {
            _send(msg.sender, owed);
        }
        emit Harvested(pid, msg.sender, owed);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
contract TimedLockFarm {
    struct Ledger {
        uint256 principal;
        uint256 debt;
        uint256 unclaimed;
    }

    uint256 private constant SCALE = 1e18;

    IERC20Like public immutable principalToken;
    IERC20Like public immutable payoutToken;
    address public immutable deployer;

    uint256 public payoutPerSecond;
    uint256 public stampedAt;
    uint256 public cumulativePerUnit;
    uint256 public principalTotal;

    mapping(address => Ledger) public ledgers;

    event Locked(address indexed who, uint256 amount);
    event Unlocked(address indexed who, uint256 amount);
    event Collected(address indexed who, uint256 amount);
    event PayoutRateChanged(uint256 oldRate, uint256 newRate);

    constructor(IERC20Like principal_, IERC20Like payout_, uint256 rate_) {
        principalToken = principal_;
        payoutToken = payout_;
        deployer = msg.sender;
        payoutPerSecond = rate_;
        stampedAt = block.timestamp;
    }

    modifier settles() {
        _poke();
        _;
    }

    modifier onlyDeployer() {
        require(msg.sender == deployer, "deployer only");
        _;
    }

    function _poke() internal {
        uint256 nowTs = block.timestamp;
        if (nowTs > stampedAt && principalTotal != 0) {
            cumulativePerUnit += ((nowTs - stampedAt) * payoutPerSecond * SCALE) / principalTotal;
        }
        stampedAt = nowTs;
    }

    function _settleUser(address who) internal {
        Ledger storage l = ledgers[who];
        uint256 entitled = (l.principal * cumulativePerUnit) / SCALE;
        l.unclaimed += entitled - l.debt;
        l.debt = entitled;
    }

    function lock(uint256 amount) external settles {
        require(amount > 0, "empty");
        _settleUser(msg.sender);

        Ledger storage l = ledgers[msg.sender];
        l.principal += amount;
        principalTotal += amount;
        l.debt = (l.principal * cumulativePerUnit) / SCALE;

        require(principalToken.transferFrom(msg.sender, address(this), amount), "pull failed");
        emit Locked(msg.sender, amount);
    }

    function unlock(uint256 amount) external settles {
        Ledger storage l = ledgers[msg.sender];
        require(amount > 0 && l.principal >= amount, "insufficient principal");
        _settleUser(msg.sender);

        l.principal -= amount;
        principalTotal -= amount;
        l.debt = (l.principal * cumulativePerUnit) / SCALE;

        require(principalToken.transfer(msg.sender, amount), "return failed");
        emit Unlocked(msg.sender, amount);
    }

    function collect() external settles {
        _settleUser(msg.sender);
        Ledger storage l = ledgers[msg.sender];
        uint256 out = l.unclaimed;
        require(out > 0, "nothing to collect");

        l.unclaimed = 0;
        require(payoutToken.transfer(msg.sender, out), "payout failed");
        emit Collected(msg.sender, out);
    }

    function setPayoutRate(uint256 newRate) external onlyDeployer settles {
        emit PayoutRateChanged(payoutPerSecond, newRate);
        payoutPerSecond = newRate;
    }
}

