pragma solidity ^0.8.20;
contract TwoSidedPairFarm {
    uint256 private constant P = 1e18;

    struct Stake {
        uint256 amountA;
        uint256 amountB;
        uint256 rptA;
        uint256 rptB;
        uint256 owedA;
        uint256 owedB;
    }

    IERC20 public immutable tokenA;
    IERC20 public immutable tokenB;
    IERC20 public immutable rewardA;
    IERC20 public immutable rewardB;
    address public immutable treasury;

    uint256 public totalA;
    uint256 public totalB;
    uint256 public rptA;
    uint256 public rptB;
    uint256 public rateA;
    uint256 public rateB;
    uint256 public lastAccrue;

    mapping(address => Stake) public stakes;

    event StakedPair(address indexed who, uint256 a, uint256 b);
    event UnstakedPair(address indexed who, uint256 a, uint256 b);
    event PairRewardClaimed(address indexed who, uint256 ra, uint256 rb);

    constructor(IERC20 a, IERC20 b, IERC20 ra, IERC20 rb, uint256 _rateA, uint256 _rateB) {
        tokenA = a;
        tokenB = b;
        rewardA = ra;
        rewardB = rb;
        rateA = _rateA;
        rateB = _rateB;
        treasury = msg.sender;
        lastAccrue = block.timestamp;
    }

    function stakeBoth(uint256 a, uint256 b) external {
        require(a > 0 && b > 0, "both sides required");
        _accruePair(msg.sender);
        Stake storage s = stakes[msg.sender];
        s.amountA += a;
        s.amountB += b;
        totalA += a;
        totalB += b;
        require(tokenA.transferFrom(msg.sender, address(this), a), "transfer A failed");
        require(tokenB.transferFrom(msg.sender, address(this), b), "transfer B failed");
        emit StakedPair(msg.sender, a, b);
    }

    function unstakeBoth(uint256 a, uint256 b) external {
        Stake storage s = stakes[msg.sender];
        require(a <= s.amountA && b <= s.amountB, "too much");
        _accruePair(msg.sender);
        s.amountA -= a;
        s.amountB -= b;
        totalA -= a;
        totalB -= b;
        require(tokenA.transfer(msg.sender, a), "transfer A failed");
        require(tokenB.transfer(msg.sender, b), "transfer B failed");
        emit UnstakedPair(msg.sender, a, b);
    }

    function claimPairRewards() external {
        _accruePair(msg.sender);
        Stake storage s = stakes[msg.sender];
        uint256 ra = s.owedA;
        uint256 rb = s.owedB;
        s.owedA = 0;
        s.owedB = 0;
        if (ra > 0) require(rewardA.transfer(msg.sender, ra), "reward A failed");
        if (rb > 0) require(rewardB.transfer(msg.sender, rb), "reward B failed");
        emit PairRewardClaimed(msg.sender, ra, rb);
    }

    /// @dev Moves both accumulators to now, then books the caller's side-specific
    /// rewards against the amounts held before this call.
    function _accruePair(address who) internal {
        uint256 dt = block.timestamp - lastAccrue;
        if (dt > 0) {
            if (totalA > 0) rptA += dt * rateA * P / totalA;
            if (totalB > 0) rptB += dt * rateB * P / totalB;
            lastAccrue = block.timestamp;
        }
        Stake storage s = stakes[who];
        s.owedA += s.amountA * (rptA - s.rptA) / P;
        s.owedB += s.amountB * (rptB - s.rptB) / P;
        s.rptA = rptA;
        s.rptB = rptB;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.23;
contract SharePricedFeeVault {
    uint256 private constant ONE = 1e18;

    IERC20 public immutable asset;
    IERC20 public immutable feeAsset;
    address public immutable collector;

    uint256 public totalShares;
    uint256 public totalAssets;
    uint256 public feePerShare;

    mapping(address => uint256) public shares;
    mapping(address => uint256) public feeDebt;
    mapping(address => uint256) public feesPending;

    event FeesReceived(uint256 amount, uint256 feePerShare);
    event Supplied(address indexed user, uint256 assets, uint256 minted);
    event Redeemed(address indexed user, uint256 shares, uint256 assets);
    event FeesWithdrawn(address indexed user, uint256 amount);

    constructor(IERC20 _asset, IERC20 _feeAsset) {
        asset = _asset;
        feeAsset = _feeAsset;
        collector = msg.sender;
    }

    function receiveFees(uint256 amount) external {
        require(msg.sender == collector, "not collector");
        require(totalShares > 0, "no shares");
        require(feeAsset.transferFrom(msg.sender, address(this), amount), "transfer failed");
        feePerShare += amount * ONE / totalShares;
        emit FeesReceived(amount, feePerShare);
    }

    function supplyAssets(uint256 assets) external {
        require(assets > 0, "zero assets");
        _bankFees(msg.sender);
        uint256 minted = totalShares == 0 || totalAssets == 0
            ? assets
            : assets * totalShares / totalAssets;
        shares[msg.sender] += minted;
        totalShares += minted;
        totalAssets += assets;
        feeDebt[msg.sender] = shares[msg.sender] * feePerShare / ONE;
        require(asset.transferFrom(msg.sender, address(this), assets), "transfer failed");
        emit Supplied(msg.sender, assets, minted);
    }

    function redeemShares(uint256 amount) external {
        require(amount <= shares[msg.sender], "insufficient shares");
        _bankFees(msg.sender);
        uint256 assets = amount * totalAssets / totalShares;
        shares[msg.sender] -= amount;
        totalShares -= amount;
        totalAssets -= assets;
        feeDebt[msg.sender] = shares[msg.sender] * feePerShare / ONE;
        require(asset.transfer(msg.sender, assets), "transfer failed");
        emit Redeemed(msg.sender, amount, assets);
    }

    function withdrawFees() external {
        _bankFees(msg.sender);
        uint256 amount = feesPending[msg.sender];
        if (amount == 0) return;
        feesPending[msg.sender] = 0;
        require(feeAsset.transfer(msg.sender, amount), "transfer failed");
        emit FeesWithdrawn(msg.sender, amount);
    }

    /// @dev Banks fees earned on the caller's current shares, then resets its debt
    /// to the present per-share index. Must run before any change to shares[who].
    function _bankFees(address who) internal {
        uint256 earned = shares[who] * feePerShare / ONE;
        if (earned > feeDebt[who]) {
            feesPending[who] += earned - feeDebt[who];
        }
        feeDebt[who] = shares[who] * feePerShare / ONE;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
contract CompactLiquidityDistributor {
    uint256 private constant INDEX_SCALE = 1e24;

    struct Position {
        uint128 liquidity;
        uint128 debt;
        uint256 unclaimed;
    }

    IERC20 public immutable liquidityAsset;
    IERC20 public immutable rewardAsset;
    address public immutable deployer;

    uint256 public index;
    uint128 public totalLiquidity;

    mapping(address => Position) public positions;

    event Committed(address indexed owner, uint128 amount);
    event Released(address indexed owner, uint128 amount);
    event Harvested(address indexed owner, uint256 amount);
    event IndexBumped(uint256 newIndex);

    constructor(IERC20 _liquidity, IERC20 _reward) {
        liquidityAsset = _liquidity;
        rewardAsset = _reward;
        deployer = msg.sender;
    }

    function bumpIndex(uint256 rewardAmount) external {
        require(msg.sender == deployer, "not deployer");
        require(totalLiquidity > 0, "no liquidity");
        require(rewardAsset.transferFrom(msg.sender, address(this), rewardAmount), "transfer failed");
        index += rewardAmount * INDEX_SCALE / totalLiquidity;
        emit IndexBumped(index);
    }

    function commitLiquidity(uint128 amount) external {
        require(amount > 0, "zero amount");
        _flushDebt(msg.sender);
        Position storage p = positions[msg.sender];
        p.liquidity += amount;
        p.debt = uint128(uint256(p.liquidity) * index / INDEX_SCALE);
        totalLiquidity += amount;
        require(liquidityAsset.transferFrom(msg.sender, address(this), amount), "transfer failed");
        emit Committed(msg.sender, amount);
    }

    function releaseLiquidity(uint128 amount) external {
        Position storage p = positions[msg.sender];
        require(amount <= p.liquidity, "insufficient");
        _flushDebt(msg.sender);
        p.liquidity -= amount;
        p.debt = uint128(uint256(p.liquidity) * index / INDEX_SCALE);
        totalLiquidity -= amount;
        require(liquidityAsset.transfer(msg.sender, amount), "transfer failed");
        emit Released(msg.sender, amount);
    }

    function harvest() external {
        _flushDebt(msg.sender);
        Position storage p = positions[msg.sender];
        uint256 amount = p.unclaimed;
        if (amount == 0) return;
        p.unclaimed = 0;
        require(rewardAsset.transfer(msg.sender, amount), "transfer failed");
        emit Harvested(msg.sender, amount);
    }

    /// @dev Converts the index growth since the stored debt into unclaimed reward.
    function _flushDebt(address owner) internal {
        Position storage p = positions[owner];
        uint256 accrued = uint256(p.liquidity) * index / INDEX_SCALE;
        if (accrued > p.debt) {
            p.unclaimed += accrued - p.debt;
        }
        p.debt = uint128(accrued);
    }
}

