pragma solidity 0.8.17;
contract StakeForFees {
    error ZeroAmount();
    error InsufficientStake(uint256 have, uint256 want);
    error TransferFailed();

    uint256 private constant ACC = 1e18;

    IERC20 public immutable stakeToken;
    IERC20 public immutable feeToken;

    uint256 public totalStaked;
    uint256 public feeAccPerShare;

    mapping(address => uint256) public stakedOf;
    mapping(address => uint256) public rewardDebtOf;
    mapping(address => uint256) public pendingFees;

    event FeesReceived(uint256 amount);
    event StakedFor(address indexed payer, address indexed beneficiary, uint256 amount);
    event Unstaked(address indexed user, uint256 amount);
    event FeesHarvested(address indexed user, uint256 amount);

    constructor(IERC20 _stake, IERC20 _fee) {
        stakeToken = _stake;
        feeToken = _fee;
    }

    function notifyFees(uint256 amount) external {
        if (totalStaked == 0) revert ZeroAmount();
        if (!feeToken.transferFrom(msg.sender, address(this), amount)) revert TransferFailed();
        feeAccPerShare += (amount * ACC) / totalStaked;
        emit FeesReceived(amount);
    }

    function _settleStaker(address who) internal {
        uint256 shares = stakedOf[who];
        if (shares > 0) {
            pendingFees[who] += (shares * (feeAccPerShare - rewardDebtOf[who])) / ACC;
        }
        rewardDebtOf[who] = feeAccPerShare;
    }

    /// @notice Stake tokens into `beneficiary`'s position.
    function stakeFor(address beneficiary, uint256 amount) external {
        if (amount == 0) revert ZeroAmount();
        _settleStaker(beneficiary);
        stakedOf[beneficiary] += amount;
        totalStaked += amount;
        if (!stakeToken.transferFrom(msg.sender, address(this), amount)) revert TransferFailed();
        emit StakedFor(msg.sender, beneficiary, amount);
    }

    /// @notice Unstake up to the caller's balance.
    function unstake(uint256 amount) external {
        if (amount == 0) revert ZeroAmount();
        _settleStaker(msg.sender);
        uint256 have = stakedOf[msg.sender];
        if (have < amount) revert InsufficientStake(have, amount);
        stakedOf[msg.sender] -= amount;
        totalStaked -= amount;
        if (!stakeToken.transfer(msg.sender, amount)) revert TransferFailed();
        emit Unstaked(msg.sender, amount);
    }

    /// @notice Harvest accrued fee share.
    function harvest() external {
        _settleStaker(msg.sender);
        uint256 amount = pendingFees[msg.sender];
        if (amount == 0) revert ZeroAmount();
        pendingFees[msg.sender] = 0;
        if (!feeToken.transfer(msg.sender, amount)) revert TransferFailed();
        emit FeesHarvested(msg.sender, amount);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.23;
contract StreamingPayroll {
    IERC20 public immutable payToken;
    address public immutable owner;

    struct Stream {
        uint256 rate;
        uint256 deposited;
        uint256 vested;
        uint256 paid;
        uint256 lastTick;
    }

    mapping(address => Stream) public streams;
    uint256 public totalDeposited;

    event StreamOpened(address indexed worker, uint256 rate);
    event Funded(address indexed funder, address indexed worker, uint256 amount);
    event Vested(address indexed worker, uint256 amount);
    event Withdrawn(address indexed worker, uint256 amount);

    constructor(IERC20 _token) {
        payToken = _token;
        owner = msg.sender;
    }

    function _accrueStream(address worker) internal {
        Stream storage s = streams[worker];
        if (s.lastTick == 0 || s.rate == 0) {
            s.lastTick = block.timestamp;
            return;
        }
        uint256 elapsed = block.timestamp - s.lastTick;
        uint256 inc = s.rate * elapsed;
        uint256 remaining = s.deposited - s.vested;
        if (inc > remaining) inc = remaining;
        s.vested += inc;
        s.lastTick = block.timestamp;
        emit Vested(worker, inc);
    }

    /// @notice Owner sets a worker's streaming rate (tokens per second).
    function openStream(address worker, uint256 ratePerSecond) external {
        require(msg.sender == owner, "not owner");
        _accrueStream(worker);
        streams[worker].rate = ratePerSecond;
        emit StreamOpened(worker, ratePerSecond);
    }

    /// @notice Fund a worker's stream. Funder pays; value joins the worker's deposit.
    function fundStream(address worker, uint256 amount) external {
        require(amount > 0, "zero amount");
        _accrueStream(worker);
        Stream storage s = streams[worker];
        s.deposited += amount;
        totalDeposited += amount;
        require(payToken.transferFrom(msg.sender, address(this), amount), "transfer failed");
        emit Funded(msg.sender, worker, amount);
    }

    /// @notice Withdraw a specific amount of vested tokens.
    function cashOut(uint256 amount) external {
        _accrueStream(msg.sender);
        Stream storage s = streams[msg.sender];
        require(s.vested - s.paid >= amount, "not vested");
        s.paid += amount;
        totalDeposited -= amount;
        require(payToken.transfer(msg.sender, amount), "transfer failed");
        emit Withdrawn(msg.sender, amount);
    }

    /// @notice Claim everything vested so far.
    function drawVested() external {
        _accrueStream(msg.sender);
        Stream storage s = streams[msg.sender];
        uint256 amount = s.vested - s.paid;
        require(amount > 0, "nothing vested");
        s.paid += amount;
        totalDeposited -= amount;
        require(payToken.transfer(msg.sender, amount), "transfer failed");
        emit Withdrawn(msg.sender, amount);
    }
}

