pragma solidity ^0.8.22;
contract VoteEscrowLock {
    uint256 public constant MAX_LOCK = 4 * 365 days;
    uint256 public constant MIN_LOCK = 7 days;

    struct Position {
        uint256 amount;
        uint256 end;
        uint256 cachedWeight;
    }

    IERC20 public immutable token;
    uint256 public totalWeight;
    uint256 public totalLocked;

    mapping(address => Position) public positions;
    mapping(address => uint256) public claimable;

    event Locked(address indexed user, uint256 amount, uint256 end, uint256 weight);
    event Unlocked(address indexed user, uint256 amount);
    event Claimed(address indexed user, uint256 amount);

    constructor(IERC20 _token) {
        token = _token;
    }

    function _currentWeight(Position storage p) internal view returns (uint256) {
        if (p.end <= block.timestamp) return 0;
        return (p.amount * (p.end - block.timestamp)) / MAX_LOCK;
    }

    function _syncWeight(address who) internal {
        Position storage p = positions[who];
        uint256 w = _currentWeight(p);
        totalWeight = totalWeight - p.cachedWeight + w;
        p.cachedWeight = w;
    }

    function lock(uint256 amount, uint256 duration) external {
        require(amount > 0, "zero");
        require(duration >= MIN_LOCK && duration <= MAX_LOCK, "duration");
        _syncWeight(msg.sender);
        Position storage p = positions[msg.sender];
        p.amount += amount;
        uint256 newEnd = block.timestamp + duration;
        if (newEnd > p.end) p.end = newEnd;
        totalLocked += amount;
        uint256 w = _currentWeight(p);
        totalWeight = totalWeight - p.cachedWeight + w;
        p.cachedWeight = w;
        emit Locked(msg.sender, amount, p.end, w);
        require(token.transferFrom(msg.sender, address(this), amount), "pull");
    }

    function unlock() external returns (uint256 amount) {
        _syncWeight(msg.sender);
        Position storage p = positions[msg.sender];
        require(p.amount > 0, "no position");
        require(block.timestamp >= p.end, "still locked");
        amount = p.amount;
        totalLocked -= amount;
        claimable[msg.sender] += amount;
        delete positions[msg.sender];
        emit Unlocked(msg.sender, amount);
    }

    function claim() external returns (uint256 amount) {
        amount = claimable[msg.sender];
        require(amount > 0, "nothing");
        claimable[msg.sender] = 0;
        emit Claimed(msg.sender, amount);
        require(token.transfer(msg.sender, amount), "xfer");
    }

    function weightOf(address who) external view returns (uint256) {
        return _currentWeight(positions[who]);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;
contract OperatorAllocationBook {
    uint256 private constant PRECISION = 1e18;
    uint256 private constant BPS = 10_000;

    struct Operator {
        address account;
        uint256 weightBps;
        uint256 totalStaked;
        uint256 rewardIndex;
        bool active;
    }

    IERC20 public immutable token;
    address public immutable admin;

    Operator[] public operators;
    uint256 public unallocatedRewards;

    mapping(uint256 => mapping(address => uint256)) public stakeOf;
    mapping(uint256 => mapping(address => uint256)) public indexPaid;
    mapping(uint256 => mapping(address => uint256)) public owed;

    event OperatorAdded(uint256 indexed id, address account, uint256 weightBps);
    event Allocated(address indexed user, uint256 indexed id, uint256 amount);
    event Released(address indexed user, uint256 indexed id, uint256 amount);
    event RewardsReported(uint256 amount);
    event RewardsClaimed(address indexed user, uint256 indexed id, uint256 amount);

    constructor(IERC20 _token) {
        token = _token;
        admin = msg.sender;
    }

    function addOperator(address account, uint256 weightBps) external {
        require(msg.sender == admin, "admin");
        require(weightBps <= BPS, "weight");
        operators.push(Operator(account, weightBps, 0, 0, true));
        emit OperatorAdded(operators.length - 1, account, weightBps);
    }

    function reportRewards(uint256 amount) external {
        require(msg.sender == admin, "admin");
        require(amount > 0, "zero");
        unallocatedRewards += amount;
        emit RewardsReported(amount);
        require(token.transferFrom(msg.sender, address(this), amount), "pull");
    }

    function _rebalanceWeights() internal {
        uint256 pool = unallocatedRewards;
        if (pool == 0) return;
        uint256 distributed;
        uint256 n = operators.length;
        for (uint256 i = 0; i < n; i++) {
            Operator storage o = operators[i];
            if (!o.active || o.totalStaked == 0) continue;
            uint256 share = (pool * o.weightBps) / BPS;
            if (share == 0) continue;
            distributed += share;
            o.rewardIndex += (share * PRECISION) / o.totalStaked;
        }
        unallocatedRewards = pool - distributed;
    }

    function _settleOwed(uint256 id, address who) internal {
        uint256 idx = operators[id].rewardIndex;
        owed[id][who] += (stakeOf[id][who] * (idx - indexPaid[id][who])) / PRECISION;
        indexPaid[id][who] = idx;
    }

    function allocateToOperator(uint256 id, uint256 amount) external {
        require(amount > 0, "zero");
        require(id < operators.length && operators[id].active, "operator");
        _rebalanceWeights();
        _settleOwed(id, msg.sender);
        stakeOf[id][msg.sender] += amount;
        operators[id].totalStaked += amount;
        emit Allocated(msg.sender, id, amount);
        require(token.transferFrom(msg.sender, address(this), amount), "pull");
    }

    function releaseAllocation(uint256 id, uint256 amount) external {
        _rebalanceWeights();
        _settleOwed(id, msg.sender);
        require(stakeOf[id][msg.sender] >= amount, "insufficient");
        stakeOf[id][msg.sender] -= amount;
        operators[id].totalStaked -= amount;
        emit Released(msg.sender, id, amount);
        require(token.transfer(msg.sender, amount), "xfer");
    }

    function claimAllocated(uint256 id) external returns (uint256 amount) {
        _rebalanceWeights();
        _settleOwed(id, msg.sender);
        amount = owed[id][msg.sender];
        require(amount > 0, "none");
        owed[id][msg.sender] = 0;
        emit RewardsClaimed(msg.sender, id, amount);
        require(token.transfer(msg.sender, amount), "xfer");
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
contract RestakeWithWithdrawalDelay {
    uint256 private constant PRECISION = 1e18;
    uint256 public constant WITHDRAW_DELAY = 7 days;

    struct Strategy {
        IERC20 token;
        uint256 totalShares;
        uint256 totalTokens;
    }

    struct Queued {
        address staker;
        uint256 strategyId;
        uint256 shares;
        uint256 tokens;
        uint256 startedAt;
    }

    address public immutable owner;
    Strategy[] public strategies;

    mapping(address => uint256) public magnitude;
    mapping(address => address) public delegatedTo;
    mapping(address => uint256) public slashSnap;
    mapping(address => mapping(uint256 => uint256)) public stakerShares;
    mapping(address => uint256) public nonces;
    mapping(bytes32 => Queued) public queued;

    event OperatorRegistered(address indexed operator);
    event OperatorSlashed(address indexed operator, uint256 bps, uint256 magnitude);
    event Delegated(address indexed staker, address indexed operator);
    event Restaked(address indexed staker, uint256 indexed strategyId, uint256 tokens, uint256 shares);
    event WithdrawalQueued(bytes32 indexed root, address indexed staker, uint256 strategyId, uint256 tokens);
    event WithdrawalCompleted(bytes32 indexed root, uint256 tokens);

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    function addStrategy(IERC20 token) external onlyOwner returns (uint256 id) {
        strategies.push(Strategy({token: token, totalShares: 0, totalTokens: 0}));
        id = strategies.length - 1;
    }

    function registerOperator(address op) external onlyOwner {
        magnitude[op] = PRECISION;
        emit OperatorRegistered(op);
    }

    function slashOperator(address op, uint256 bps) external onlyOwner {
        require(bps <= 10_000, "bps");
        require(magnitude[op] > 0, "unregistered");
        magnitude[op] = (magnitude[op] * (10_000 - bps)) / 10_000;
        emit OperatorSlashed(op, bps, magnitude[op]);
    }

    function _operatorMagnitude(address op) internal view returns (uint256) {
        if (op == address(0)) return PRECISION;
        return magnitude[op];
    }

    function _syncStakerView(address staker) internal {
        uint256 idx = _operatorMagnitude(delegatedTo[staker]);
        uint256 snap = slashSnap[staker];
        if (snap == 0) {
            slashSnap[staker] = idx;
            return;
        }
        if (snap == idx) return;
        uint256 n = strategies.length;
        for (uint256 i = 0; i < n; i++) {
            stakerShares[staker][i] = (stakerShares[staker][i] * idx) / snap;
        }
        slashSnap[staker] = idx;
    }

    function delegate(address op) external {
        require(delegatedTo[msg.sender] == address(0), "already delegated");
        require(slashSnap[msg.sender] == 0, "has restake history");
        require(magnitude[op] > 0, "unregistered");
        delegatedTo[msg.sender] = op;
        emit Delegated(msg.sender, op);
    }

    function depositToStrategy(uint256 strategyId, uint256 amount) external {
        require(strategyId < strategies.length, "strategy");
        require(amount > 0, "zero");
        _syncStakerView(msg.sender);
        Strategy storage s = strategies[strategyId];
        uint256 minted = s.totalTokens == 0 ? amount : (amount * s.totalShares) / s.totalTokens;
        require(minted > 0, "dust");
        stakerShares[msg.sender][strategyId] += minted;
        s.totalShares += minted;
        s.totalTokens += amount;
        emit Restaked(msg.sender, strategyId, amount, minted);
        require(s.token.transferFrom(msg.sender, address(this), amount), "pull");
    }

    function queueWithdrawal(uint256 strategyId, uint256 shares) external returns (bytes32 root) {
        require(shares > 0, "zero");
        _syncStakerView(msg.sender);
        require(stakerShares[msg.sender][strategyId] >= shares, "insufficient");
        Strategy storage s = strategies[strategyId];
        uint256 tokens = (shares * s.totalTokens) / s.totalShares;
        stakerShares[msg.sender][strategyId] -= shares;
        s.totalShares -= shares;
        s.totalTokens -= tokens;
        nonces[msg.sender] += 1;
        root = keccak256(abi.encode(msg.sender, strategyId, nonces[msg.sender], block.timestamp));
        queued[root] = Queued({staker: msg.sender, strategyId: strategyId, shares: shares, tokens: tokens, startedAt: block.timestamp});
        emit WithdrawalQueued(root, msg.sender, strategyId, tokens);
    }

    function completeWithdrawal(bytes32 root) external returns (uint256 tokens) {
        Queued storage q = queued[root];
        require(q.staker == msg.sender, "not staker");
        require(block.timestamp >= q.startedAt + WITHDRAW_DELAY, "delay");
        tokens = q.tokens;
        IERC20 tok = strategies[q.strategyId].token;
        delete queued[root];
        emit WithdrawalCompleted(root, tokens);
        require(tok.transfer(msg.sender, tokens), "xfer");
    }
}
